    pub fn layout_new(size: u64, align: u64) -> Result<Layout, String> {
        if align == 0 {
        return Err(("Alignment must be a power of two".to_string()).to_string());
    };
        let align_mask = align - 1;
        let align_remainder = align & align_mask;
        if align_remainder != 0 {
        return Err(("Alignment must be a power of two".to_string()).to_string());
    };
        if size % align != 0 {
        return Err(("Size must be a multiple of alignment".to_string()).to_string());
    };
        Ok(Layout { size: size, align: align })
    }
    
    pub fn layout_from_size_align_unchecked(size: u64, align: u64) -> Layout {
        Layout { size: size, align: align }
    }
    
    pub fn layout_for<T>() -> Layout {
        Layout { size: size_of(), align: align_of() }
    }
    
    pub fn layout_array<T>(count: u64) -> Result<Layout, String> {
        let elem_layout = layout_for();
        let array_size = elem_layout.size * count;
        if count != 0 && array_size / count != elem_layout.size {
        return Err(("Array size overflow".to_string()).to_string());
    };
        layout_new(array_size, elem_layout.align)
    }
    
