        state[(c) as usize] = state[(c) as usize].clone() + state[(d) as usize].clone();
        state[(b) as usize] = left_rotate(state[(b) as usize].clone() ^ state[(c) as usize].clone(), 12);
        state[(a) as usize] = state[(a) as usize].clone() + state[(b) as usize].clone();
        state[(d) as usize] = left_rotate(state[(d) as usize].clone() ^ state[(a) as usize].clone(), 8);
        state[(c) as usize] = state[(c) as usize].clone() + state[(d) as usize].clone();
