        p.r[(1) as usize] = u32_from_le_at(key, 3) >> 2 & 0x3FFFF03;
        p.r[(2) as usize] = u32_from_le_at(key, 6) >> 4 & 0x3FFC0FF;
        p.r[(3) as usize] = u32_from_le_at(key, 9) >> 6 & 0x3F03FFF;
        p.r[(4) as usize] = u32_from_le_at(key, 12) >> 8 & 0x00FFFFF;
        p.pad[(0) as usize] = u32_from_le_at(key, 16);
        p.pad[(1) as usize] = u32_from_le_at(key, 20);
        p.pad[(2) as usize] = u32_from_le_at(key, 24);
        p.pad[(3) as usize] = u32_from_le_at(key, 28);
        p
