    pub fn _fe_cswap(f: &mut Fe25519, g: &mut Fe25519, swap: i64) -> () {
        let mask = 0 - swap;
        for i in 0..10 {
            let x = mask & f.v[(i) as usize].clone() ^ g.v[(i) as usize].clone();
            f.v[(i) as usize] = f.v[(i) as usize].clone() ^ x;
            g.v[(i) as usize] = g.v[(i) as usize].clone() ^ x;
        }
    }
    
