        h.v[(4) as usize] = ((s[(13) as usize].clone()) as i64) | ((s[(14) as usize].clone()) as i64) << 8 | ((s[(15) as usize].clone()) as i64) << 16 << 2;
        h.v[(5) as usize] = ((s[(16) as usize].clone()) as i64) | ((s[(17) as usize].clone()) as i64) << 8 | ((s[(18) as usize].clone()) as i64) << 16 | ((s[(19) as usize].clone()) as i64) << 24;
