    pub fn x25519_generate_keypair() -> ([u8; 32], [u8; 32]) {
        let private_key_bytes = random_bytes(32);
        let mut private_key = vec![0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8, 0u8];
        for i in 0..32 {
            private_key[(i) as usize] = private_key_bytes[(i) as usize].clone();
        }
        let public_key = x25519(&private_key, &X25519_BASEPOINT);
        (private_key, public_key)
    }
    
