    pub fn RUBY_Qnil() -> RubyValue {
        RubyValue { raw: 0x08 }
    }
    
    pub fn RUBY_Qtrue() -> RubyValue {
        RubyValue { raw: 0x14 }
    }
    
    pub fn RUBY_Qfalse() -> RubyValue {
        RubyValue { raw: 0x00 }
    }
    
    pub fn ruby_nil_p(v: RubyValue) -> bool {
        v.raw == RUBY_Qnil().raw
    }
    
    pub fn ruby_fixnum_p(v: RubyValue) -> bool {
        v.raw & 1 == 1
    }
    
    pub fn int_to_ruby_fixnum(n: i64) -> RubyValue {
        RubyValue { raw: ((n) as u64) << 1 | 1 }
    }
    
    pub fn ruby_fixnum_to_int(v: RubyValue) -> i64 {
        ((v.raw >> 1) as i64)
    }
    
