    pub fn tg_string_to_ruby(s: String) -> RubyValue {
        let cs = cstring_new(s);
        rb_str_new_cstr(cstring_as_ptr(&cs))
    }
    
    pub fn ruby_to_tg_string(v: RubyValue) -> Result<String, String> {
        let rtype = rb_type(v);
        if rtype != RUBY_T_STRING() {
        let to_s_id = rb_intern(cstring_as_ptr(&cstring_new("to_s".to_string())));
        let sv = rb_funcall(v, to_s_id, 0);
        let sv_type = rb_type(sv);
        if sv_type != RUBY_T_STRING() {
        return Err("Ruby value could not be converted to String via to_s".to_string());
    };
        let mut sv_holder = sv;
        let sv_cptr = rb_string_value_cstr(((&mut sv_holder) as Ptr<RubyValue>));
        if sv_cptr.address == 0 {
        return Err("Ruby to_s conversion returned null".to_string());
    };
        return Ok(String::from_c_str(sv_cptr));
    };
        let mut val_holder = v;
        let cptr = rb_string_value_cstr(((&mut val_holder) as Ptr<RubyValue>));
        if cptr.address == 0 {
        Err("Ruby string conversion returned null".to_string())
    } else {
        Ok(String::from_c_str(cptr))
    }
    }
    
    pub fn tg_int_to_ruby(n: i64) -> RubyValue {
        rb_int2num(n)
    }
    
    pub fn ruby_to_tg_int(v: RubyValue) -> i64 {
        if ruby_fixnum_p(v) {
        ruby_fixnum_to_int(v)
    } else {
        rb_num2int(v)
    }
    }
    
    pub fn tg_float_to_ruby(f: f64) -> RubyValue {
        rb_float_new(f)
    }
    
    pub fn ruby_to_tg_float(v: RubyValue) -> f64 {
        rb_num2dbl(v)
    }
    
    pub fn tg_bool_to_ruby(b: bool) -> RubyValue {
        if b {
        RUBY_Qtrue()
    } else {
        RUBY_Qfalse()
    }
    }
    
    pub fn ruby_to_tg_bool(v: RubyValue) -> bool {
        v.raw != RUBY_Qfalse().raw && v.raw != RUBY_Qnil().raw
    }
    
    pub fn tg_unit_to_ruby() -> RubyValue {
        RUBY_Qnil()
    }
    
