    pub fn ruby_start() -> Result<RubyRuntime, String> {
        ruby_runtime_lock();
        match RUBY_RUNTIME { Option::Some(_) => {
        ruby_runtime_unlock();
        return Err("Ruby runtime already initialized".to_string());
    }, Option::None => {
        ()
    } };
        ruby_init();
        ruby_init_loadpath();
        let rt = RubyRuntime { initialized: true };
        RUBY_RUNTIME = Option::Some(rt);
        ruby_runtime_unlock();
        Ok(rt)
    }
    
    pub fn ruby_stop() -> () {
        ruby_runtime_lock();
        match RUBY_RUNTIME { Option::Some(_) => {
        ruby_finalize();
        RUBY_RUNTIME = Option::None;
    }, Option::None => {
        ()
    } };
        ruby_runtime_unlock();
    }
    
    pub fn ruby_call(recv: RubyValue, method: String) -> RubyValue {
        let mid = rb_intern(cstring_as_ptr(&cstring_new(method)));
        rb_funcall(recv, mid, 0)
    }
    
    pub fn ruby_call1(recv: RubyValue, method: String, arg1: RubyValue) -> RubyValue {
        let mid = rb_intern(cstring_as_ptr(&cstring_new(method)));
        let mut args = Vec::new();
        args.push(arg1);
        rb_funcall2(recv, mid, 1, ((args.as_ptr_address()) as Ptr<RubyValue>))
    }
    
    pub fn ruby_call2(recv: RubyValue, method: String, arg1: RubyValue, arg2: RubyValue) -> RubyValue {
        let mid = rb_intern(cstring_as_ptr(&cstring_new(method)));
        let mut args = Vec::new();
        args.push(arg1);
        args.push(arg2);
        rb_funcall2(recv, mid, 2, ((args.as_ptr_address()) as Ptr<RubyValue>))
    }
    
    pub fn ruby_call_args(recv: RubyValue, method: String, args: &Vec<RubyValue>) -> RubyValue {
        let mid = rb_intern(cstring_as_ptr(&cstring_new(method)));
        rb_funcall2(recv, mid, (args.len() as i64), ((args.as_ptr_address()) as Ptr<RubyValue>))
    }
    
    pub fn ruby_eval(code: String) -> Result<RubyValue, String> {
        let cs = cstring_new(code);
        let mut state = 0;
        let result = rb_eval_string_protect(cstring_as_ptr(&cs), ((&mut state) as Ptr<i64>));
        if state != 0 {
        let exc = ruby_call(result, "message".to_string());
        match ruby_to_tg_string(exc) { Result::Ok(msg) => {
        Err(format!("{}{}", "Ruby exception: ".to_string(), msg))
    }, Result::Err(_) => {
        Err("Ruby exception (could not read message)".to_string())
    } }
    } else {
        Ok(result)
    }
    }
    
