pub mod fmt {
    use super::*;
    use crate::core::Display;
    use crate::fmt::int_to_string_intrinsic;
    
    trait Debug {
        fn debug(&self) -> String;
    }
    
    extern "Rust" {
        fn print(x: String) -> ();
        fn puts(x: String) -> ();
        fn eprint(x: String) -> ();
        fn eputs(x: String) -> ();
    }
    
    pub fn format(fmt: String, args: Array<String>) -> String {
        let mut result = "".to_string();
        let mut arg_idx = 0;
        let mut i = 0;
        let chars = fmt.chars();
        let len = (chars.len() as i64);
        while i < len {
            let ch = chars[(i) as usize].clone();
            if ch == '{' {
        if i + 1 < len && chars[(i + 1) as usize].clone() == '{' {
        result = format!("{}{}", result, "{".to_string());
        i = i + 2;
    } else {
        let start = i + 1;
        let mut end_idx = start;
        while end_idx < len && chars[(end_idx) as usize].clone() != '}' {
            end_idx = end_idx + 1;
        }
        if end_idx >= len {
        result = format!("{}{}", result, "{".to_string());
        i = i + 1;
    } else {
        let inner = fmt.slice(start, end_idx);
        if inner.is_empty() {
        if arg_idx < (args.len() as i64) {
        result = result + args[(arg_idx) as usize].clone();
        arg_idx = arg_idx + 1;
    } else {
        result = format!("{}{}", result, "{}".to_string());
    }
    } else {
        match parse_int(inner) { Option::Some(idx) => {
        if idx >= 0 && idx < (args.len() as i64) {
        result = result + args[(idx) as usize].clone();
    } else {
        result = format!("{}{}", format!("{}{}", format!("{}{}", result, "{".to_string()), inner), "}".to_string());
    }
    }, Option::None => {
        result = format!("{}{}", format!("{}{}", format!("{}{}", result, "{".to_string()), inner), "}".to_string());
    } }
    };
        i = end_idx + 1;
    }
    }
    } else if ch == '}' && i + 1 < len && chars[(i + 1) as usize].clone() == '}' {
        result = format!("{}{}", result, "}".to_string());
        i = i + 2;
    } else {
        result = format!("{}{}", result, (ch).to_string());
        i = i + 1;
    }
        }
        result
    }
    
    pub fn parse_int(s: String) -> Option<i64> {
        if s.is_empty() {
        return Option::None;
    };
        let mut result = 0;
        let mut negative = false;
        let mut start = 0;
        if s.chars().nth((0) as usize).unwrap() == '-' {
        negative = true;
        start = 1;
    };
        let mut i = start;
        let chars = s.chars();
        while i < (chars.len() as i64) {
            let ch = chars[(i) as usize].clone();
            if ch >= '0' && ch <= '9' {
        result = result * 10 + ch.to_int() - '0'.to_int();
    } else {
        return Option::None;
    };
            i = i + 1;
        }
        if negative {
        result = -result;
    };
        Option::Some(result)
    }
    
    extern "Rust" {
        fn int_to_string_intrinsic(x: i64) -> String;
        fn uint_to_string_intrinsic(x: u64) -> String;
        fn float_to_string_intrinsic(x: f64) -> String;
    }
    
    pub fn to_string(x: i64) -> String {
        int_to_string_intrinsic(x)
    }
    
    pub fn int_to_string(x: i64) -> String {
        int_to_string_intrinsic(x)
    }
    
    pub fn bool_to_string(x: bool) -> String {
        if x {
        "true".to_string()
    } else {
        "false".to_string()
    }
    }
    
    pub fn display_width(s: &String) -> u64 {
        let mut width = 0u64;
        for ch in (s.chars()).clone() {
            width = width + char_width(ch);
        }
        width
    }
    
    pub fn char_width(ch: char) -> u64 {
        let cp = ((ch) as u32);
        if cp == 0 || cp >= 0x01 && cp <= 0x1F || cp == 0x7F {
        return 0u64;
    };
        if cp >= 0x20 && cp < 0x7F {
        return 1u64;
    };
        if is_combining(cp) {
        return 0u64;
    };
        if is_wide(cp) {
        return 2u64;
    };
        1u64
    }
    
    pub fn is_combining(cp: u32) -> bool {
        cp >= 0x0300 && cp <= 0x036F || cp >= 0x1AB0 && cp <= 0x1AFF || cp >= 0x1DC0 && cp <= 0x1DFF || cp >= 0x20D0 && cp <= 0x20FF || cp >= 0xFE20 && cp <= 0xFE2F
    }
    
    pub fn is_wide(cp: u32) -> bool {
        cp >= 0x1100 && cp <= 0x115F || cp >= 0x2E80 && cp <= 0x9FFF || cp >= 0xAC00 && cp <= 0xD7A3 || cp >= 0xF900 && cp <= 0xFAFF || cp >= 0xFE10 && cp <= 0xFE1F || cp >= 0xFE30 && cp <= 0xFE6F || cp >= 0xFF00 && cp <= 0xFF60 || cp >= 0xFFE0 && cp <= 0xFFE6 || cp >= 0x20000 && cp <= 0x2FFFF
    }
    
}

