    pub fn file_read(f: &File, buf: &mut Vec<u8>, max_bytes: i64) -> Result<i64, IOError> {
        if !f.is_open {
        return Err(IOError::Other("File is not open".to_string()));
    };
        let start = (buf.len() as i64);
        let mut i = 0;
        while i < max_bytes {
            buf.push(0);
            i = i + 1;
        }
        let n = read(f.fd, buf.as_ptr().offset(start), max_bytes);
        if n < 0 {
        buf.truncate(start);
        Err(IOError::Other(format!("{}{}", "Read error on: ".to_string(), f.path)))
    } else {
        buf.truncate(start + ((n) as u64));
        Ok(n)
    }
    }
    
