    pub fn find_crlf(buf: &Vec<u8>) -> Option<u64> {
        if (buf.len() as i64) < 2 {
        return Option::None;
    };
        for i in 0..(buf.len() as i64) - 1 {
            if buf[(i) as usize].clone() == (('\r') as u8) && buf[(i + 1) as usize].clone() == (('\n') as u8) {
        return Option::Some(i);
    }
        }
        Option::None
    }
    
