    pub fn parse(input: &str) -> Result<Value, JsonError> {
        let mut parser = JsonParser::new(input);
        parser.parse_value()
    }
    
    pub fn stringify(value: &Value) -> String {
        let mut s = JsonStringifier::new();
        s.write_value(value);
        s.finish()
    }
    
    pub fn stringify_pretty(value: &Value, indent: u64) -> String {
        let mut s = JsonStringifier::new_pretty(indent);
        s.write_value(value);
        s.finish()
    }
    
    pub fn to_json<T: Serialize>(v: &T) -> Result<String, SerError> {
        let mut s = JsonSerializer::new();
        v.serialize(&mut s)?;
        Ok(s.finish())
    }
    
    pub fn to_json_pretty<T: Serialize>(v: &T, indent: u64) -> Result<String, SerError> {
        let mut s = JsonSerializer::new_pretty(indent);
        v.serialize(&mut s)?;
        Ok(s.finish())
    }
    
    pub fn from_json<T: Deserialize>(input: &str) -> Result<T, JsonError> {
        let value = parse(input)?;
        let mut d = JsonDeserializer::new(&value);
        match T::deserialize(&mut d) { Result::Ok(v) => {
        Ok(v)
    }, Result::Err(e) => {
        Err(JsonError::Deserialize(Error::new(ErrorCode::InvalidArg, "deserialization error".to_string(), "json".to_string())))
    } }
    }
    
