    pub fn parse_bool(&mut self) -> Result<Value, JsonError> {
        if self.matches("true".to_string()) {
        Ok(Value::Bool(true))
    } else if self.matches("false".to_string()) {
        Ok(Value::Bool(false))
    } else {
        match self.peek() { Option::Some(_) => {
        Err(JsonError::UnexpectedChar(Error::new(ErrorCode::InvalidArg, "expected bool".to_string(), "json".to_string())))
    }, Option::None => {
        Err(JsonError::UnexpectedEof(Error::new(ErrorCode::IOError, "unexpected eof".to_string(), "json".to_string())))
    } }
    }
    }
    
    pub fn parse_null(&mut self) -> Result<Value, JsonError> {
        if self.matches("null".to_string()) {
        Ok(Value::Null)
    } else {
        match self.peek() { Option::Some(_) => {
        Err(JsonError::UnexpectedChar(Error::new(ErrorCode::InvalidArg, "expected null".to_string(), "json".to_string())))
    }, Option::None => {
        Err(JsonError::UnexpectedEof(Error::new(ErrorCode::IOError, "unexpected eof".to_string(), "json".to_string())))
    } }
    }
    }
    
    pub fn matches(&mut self, s: &str) -> bool {
        let len = (s.len() as i64);
        if self.pos + len > (self.input.len() as i64) {
        return false;
    };
        for i in 0..len {
            if self.input.chars().nth((self.pos + i) as usize).unwrap() != s.chars().nth((i) as usize).unwrap() {
        return false;
    }
        }
        self.pos = self.pos + len;
        self.column = self.column + len;
        true
    }
    
    #[derive(Clone)]
    struct JsonStringifier {
        output: String,
        pretty: bool,
        indent: u64,
        depth: u64,
    }
    
    impl JsonStringifier {
        fn new() -> JsonStringifier {
            JsonStringifier { output: String::new(), pretty: false, indent: 0, depth: 0 }
        }
        fn new_pretty(indent: u64) -> JsonStringifier {
            JsonStringifier { output: String::new(), pretty: true, indent: indent, depth: 0 }
        }
        fn finish(&self) -> String {
            self.output.clone()
        }
        fn write_value(&mut self, v: &Value) -> () {
            match v { Value::Null => {
        self.output.push_str("null".to_string())
    }, Value::Bool(b) => {
        if b {
        self.output.push_str("true".to_string())
    } else {
        self.output.push_str("false".to_string())
    }
    }, Value::Int(i) => {
        self.output.push_str((i).to_string().as_str())
    }, Value::Float(f) => {
        self.output.push_str((f).to_string().as_str())
    }, Value::String(s) => {
        self.write_string(&s)
    }, Value::Array(arr) => {
        self.write_array(&arr)
    }, Value::Object(obj) => {
        self.write_object(&obj)
    } };
        }
        fn write_string(&mut self, s: &String) -> () {
            self.output.push('\"');
            for c in (s.chars()).clone() {
                match c { '\"' => {
        self.output.push_str("\\\"".to_string())
    }, '\\' => {
        self.output.push_str("\\\\".to_string())
    }, '\n' => {
        self.output.push_str("\\n".to_string())
    }, '\r' => {
        self.output.push_str("\\r".to_string())
    }, '\t' => {
        self.output.push_str("\\t".to_string())
    }, _ => {
        let cp = ((c) as u64);
        if cp < 0x20 {
        self.output.push_str("\\u".to_string());
        self.output.push_str(format_hex4(cp).as_str())
    } else if cp > 0xFFFF {
        let adj = cp - 0x10000;
        let high = 0xD800 + adj >> 10;
        let low = 0xDC00 + adj & 0x3FF;
        self.output.push_str("\\u".to_string());
        self.output.push_str(format_hex4(high).as_str());
        self.output.push_str("\\u".to_string());
        self.output.push_str(format_hex4(low).as_str())
    } else {
        self.output.push(c)
    }
    } }
            }
            self.output.push('\"');
        }
        fn write_array(&mut self, arr: &Vec<Value>) -> () {
            self.output.push('[');
            if self.pretty && !arr.is_empty() {
        self.depth = self.depth + 1;
        self.write_newline()
    };
            for i in 0..(arr.len() as i64) {
                if i > 0 {
        self.output.push(',');
        if self.pretty {
        self.write_newline()
    }
    };
                if self.pretty {
        self.write_indent()
    };
                match arr.get(&i) { Option::Some(v) => {
        self.write_value(&v)
    }, Option::None => {
        ()
    } }
            }
            if self.pretty && !arr.is_empty() {
        self.depth = self.depth - 1;
        self.write_newline();
        self.write_indent()
    };
            self.output.push(']');
        }
        fn write_object(&mut self, obj: &Map<String, Value>) -> () {
            self.output.push('{');
            if self.pretty && !obj.is_empty() {
        self.depth = self.depth + 1;
        self.write_newline()
    };
            let mut first = true;
            for entry in (obj).clone() {
                let (k, v) = entry;
                if !first {
        self.output.push(',');
        if self.pretty {
        self.write_newline()
    }
    };
                first = false;
                if self.pretty {
        self.write_indent()
    };
                self.write_string(&k);
                self.output.push(':');
                if self.pretty {
        self.output.push(' ')
    };
                self.write_value(&v)
            }
            if self.pretty && !obj.is_empty() {
        self.depth = self.depth - 1;
        self.write_newline();
        self.write_indent()
    };
            self.output.push('}');
        }
        fn write_newline(&mut self) -> () {
            self.output.push('\n');
        }
        fn write_indent(&mut self) -> () {
            for _ in 0..self.depth * self.indent {
                self.output.push(' ')
            }
        }
    }
    
    #[derive(Clone)]
