    pub fn abs(x: f64) -> f64 {
        fabs(x)
    }
    
    pub fn degrees(radians: f64) -> f64 {
        radians * 180.0 / PI
    }
    
    pub fn radians(degrees: f64) -> f64 {
        degrees * PI / 180.0
    }
    
    pub fn clamp(x: f64, lo: f64, hi: f64) -> f64 {
        if x < lo {
        lo
    } else if x > hi {
        hi
    } else {
        x
    }
    }
    
    pub fn lerp(a: f64, b: f64, t: f64) -> f64 {
        a + b - a * t
    }
    
    pub fn is_nan(x: f64) -> bool {
        x != x
    }
    
    pub fn is_infinite(x: f64) -> bool {
        x == INFINITY || x == NEG_INFINITY
    }
    
    pub fn is_finite(x: f64) -> bool {
        !is_nan(x) && !is_infinite(x)
    }
    
    pub fn approx_eq(a: f64, b: f64, epsilon: f64) -> bool {
        fabs(a - b) <= epsilon
    }
    
    pub fn gcd(a: i64, b: i64) -> i64 {
        let mut x = if a < 0 {
        -a
    } else {
        a
    };
        let mut y = if b < 0 {
        -b
    } else {
        b
    };
        while y != 0 {
            let t = y;
            y = x % y;
            x = t;
        }
        x
    }
    
    pub fn lcm(a: i64, b: i64) -> i64 {
        if a == 0 || b == 0 {
        0
    } else {
        a / gcd(a, b) * b
    }
    }
    
    pub fn factorial(n: i64) -> i64 {
        if n <= 1 {
        1
    } else {
        let mut result = 1;
        for i in 2..=n {
            result = result * i;
        }
        result
    }
    }
    
    pub fn pow_int(base: i64, exp: i64) -> i64 {
        if exp == 0 {
        return 1;
    };
        let mut result = 1;
        let mut b = base;
        let mut e = exp;
        while e > 0 {
            if e % 2 == 1 {
        result = result * b;
    };
            b = b * b;
            e = e / 2;
        }
        result
    }
    
    pub fn is_prime(n: i64) -> bool {
        if n < 2 {
        return false;
    };
        if n < 4 {
        return true;
    };
        if n % 2 == 0 || n % 3 == 0 {
        return false;
    };
        let mut i = 5;
        while i * i <= n {
            if n % i == 0 || n % i + 2 == 0 {
        return false;
    };
            i = i + 6;
        }
        true
    }
    
    #[derive(Clone)]
    pub struct BigInt {
        negative: bool,
        digits: Vec<u64>,
    }
    
    impl BigInt {
        fn zero() -> BigInt {
            BigInt { negative: false, digits: Vec::from(vec![0u32]) }
        }
        fn one() -> BigInt {
            BigInt { negative: false, digits: Vec::from(vec![1u32]) }
        }
        fn from_int(value: i64) -> BigInt {
            if value == 0 {
        return BigInt.zero();
    };
            let neg = value < 0;
            let mut v = if neg {
        ((-value) as u64)
    } else {
        ((value) as u64)
    };
            let mut digs = Vec.new();
            while v > 0 {
                digs.push(((v & 0xFFFFFFFF) as u64));
                v = v >> 32;
            }
            BigInt { negative: neg, digits: digs }
        }
        fn from_string(s: String) -> Result<BigInt, String> {
            if (s.len() as i64) == 0 {
        return Err("empty string".to_string());
    };
            let mut start = 0;
            let mut neg = false;
            if s.chars().nth((0) as usize).unwrap() == '-' {
        neg = true;
        start = 1;
    } else if s.chars().nth((0) as usize).unwrap() == '+' {
        start = 1;
    };
            if start >= (s.len() as i64) {
        return Err("no digits".to_string());
    };
            let mut result = BigInt.zero();
            let ten = BigInt.from_int(10);
            for i in start..(s.len() as i64) {
                let ch = s.chars().nth((i) as usize).unwrap();
                if ch < '0' || ch > '9' {
        return Err(format!("{}{}", "invalid digit: ".to_string(), (ch).to_string()));
    };
                let digit = ((ch) as i64) - (('0') as i64);
                result = result.mul(ten).add(BigInt.from_int(digit));
            }
            result.negative = neg && !result.is_zero();
            Ok(result)
        }
        fn is_zero(&self) -> bool {
            (self.digits.len() as i64) == 1 && self.digits.get(&0) == Some(0u32)
        }
        fn negate(&self) -> BigInt {
            if self.is_zero() {
        return self.clone();
    };
            BigInt { negative: !self.negative, digits: self.digits.clone() }
        }
        fn abs(&self) -> BigInt {
            BigInt { negative: false, digits: self.digits.clone() }
        }
        fn add(&self, other: BigInt) -> BigInt {
            if self.negative == other.negative {
        let sum_digits = _add_unsigned(self.digits, other.digits);
        BigInt { negative: self.negative, digits: sum_digits }
    } else if _cmp_unsigned(self.digits, other.digits) >= 0 {
        let diff = _sub_unsigned(self.digits, other.digits);
        BigInt { negative: self.negative, digits: diff }
    } else {
        let diff = _sub_unsigned(other.digits, self.digits);
        BigInt { negative: other.negative, digits: diff }
    }
        }
        fn sub(&self, other: BigInt) -> BigInt {
            self.add(other.negate())
        }
        fn mul(&self, other: BigInt) -> BigInt {
            if self.is_zero() || other.is_zero() {
        return BigInt.zero();
    };
            let product = _mul_unsigned(self.digits, other.digits);
            BigInt { negative: self.negative != other.negative, digits: product }
        }
        fn div(&self, other: BigInt) -> BigInt {
            let (quotient, _) = _div_mod_unsigned(self.digits, other.digits);
            let neg = self.negative != other.negative;
            let mut result = BigInt { negative: neg, digits: quotient };
            if result.is_zero() {
        result.negative = false;
    };
            result
        }
        fn modulo(&self, other: BigInt) -> BigInt {
            let (_, remainder) = _div_mod_unsigned(self.digits, other.digits);
            let mut result = BigInt { negative: self.negative, digits: remainder };
            if result.is_zero() {
        result.negative = false;
    };
            result
        }
        fn pow(&self, exp: i64) -> BigInt {
            if exp == 0 {
        return BigInt.one();
    };
            let mut result = BigInt.one();
            let mut base = self;
            let mut e = exp;
            while e > 0 {
                if e % 2 == 1 {
        result = result.mul(base);
    };
                base = base.mul(base);
                e = e / 2;
            }
            result
        }
        fn compare(&self, other: BigInt) -> i64 {
            if self.negative && !other.negative {
        return -1;
    };
            if !self.negative && other.negative {
        return 1;
    };
            let ucmp = _cmp_unsigned(self.digits, other.digits);
            if self.negative {
        -ucmp
    } else {
        ucmp
    }
        }
        fn to_string(&self) -> String {
            if self.is_zero() {
        return "0".to_string();
    };
            let mut current = self.abs();
            let ten = BigInt.from_int(10);
            let mut chars = Vec.new();
            while !current.is_zero() {
                let (q, r) = _div_mod_unsigned(current.digits, ten.digits);
                let digit = if (r.len() as i64) > 0 {
        r.get(&0).unwrap_or(0u32)
    } else {
        0u32
    };
                chars.push((((digit) as i64)).to_string());
                current = BigInt { negative: false, digits: q };
            }
            let mut result = if self.negative {
        "-".to_string()
    } else {
        "".to_string()
    };
            for i in (0..(chars.len() as i64).rev()).clone() {
                result = result + chars.get(&i).unwrap_or("0".to_string());
            }
            result
        }
    }
    
    impl Display for BigInt {
        fn fmt(&self, f: &mut crate::fmt::Formatter) -> crate::fmt::Result {
            f.write_str((self).to_string())
        }
    }
    
    impl Eq for BigInt {
        fn eq(&self, other: &BigInt) -> bool {
            self.compare(*other) == 0
        }
    }
    
    impl Ord for BigInt {
        fn cmp(&self, other: &BigInt) -> Ordering {
            let ord = self.compare(*other);
            if ord < 0 {
        Ordering::Less
    } else if ord > 0 {
        Ordering::Greater
    } else {
        Ordering::Equal
    }
        }
    }
    
