    pub fn sum(values: &[f64]) -> f64 {
        let mut s = 0.0;
        for v in (values).clone() {
            s = s + v;
        }
        s
    }
    
    pub fn mean(values: &[f64]) -> f64 {
        sum(values) / (((values.len() as i64)) as f64)
    }
    
    pub fn variance(values: &[f64]) -> f64 {
        let m = mean(values);
        let mut s = 0.0;
        for v in (values).clone() {
            let d = v - m;
            s = s + d * d;
        }
        s / (((values.len() as i64) - 1) as f64)
    }
    
    pub fn stddev(values: &[f64]) -> f64 {
        sqrt(variance(values))
    }
    
    pub fn median(values: &mut [f64]) -> f64 {
        values.sort();
        let n = (values.len() as i64);
        if n % 2 == 1 {
        values[(n / 2) as usize].clone()
    } else {
        values[(n / 2 - 1) as usize].clone() + values[(n / 2) as usize].clone() / 2.0
    }
    }
    
