    static F_SETFL: () = 4;
    
    static O_NONBLOCK: () = 0x0004;
    
    static O_CLOEXEC: () = 0x1000000;
    
    #[derive(Clone)]
    struct Pipe {
        read_fd: i64,
        write_fd: i64,
    }
    
    pub fn pipe_create() -> Result<Pipe, OsError> {
        let mut fds = vec![0, 0];
        let ret = pipe(&mut fds);
        if ret < 0 {
        return Err(OsError::from_errno());
    };
        Ok(Pipe { read_fd: fds[(0) as usize].clone(), write_fd: fds[(1) as usize].clone() })
    }
    
    impl Pipe {
        fn read(&self, buf: &mut [u8]) -> Result<u64, OsError> {
            let n = c_read(self.read_fd, ((buf.as_mut_ptr()) as &mut Void), (buf.len() as i64));
            if n < 0 {
        Err(OsError::from_errno())
    } else {
        Ok(((n) as u64))
    }
        }
        fn write(&self, data: &[u8]) -> Result<u64, OsError> {
            let n = c_write(self.write_fd, ((data.as_ptr()) as &Void), (data.len() as i64));
            if n < 0 {
        Err(OsError::from_errno())
    } else {
        Ok(((n) as u64))
    }
        }
        fn close_read(&mut self) -> () {
            if self.read_fd >= 0 {
        c_close(self.read_fd);
        self.read_fd = -1;
    };
        }
        fn close_write(&mut self) -> () {
            if self.write_fd >= 0 {
        c_close(self.write_fd);
        self.write_fd = -1;
    };
        }
        fn set_nonblocking(&self) -> Result<(), OsError> {
            let flags = fcntl(self.read_fd, F_GETFL, 0);
            if flags < 0 {
        return Err(OsError::from_errno());
    };
            let ret = fcntl(self.read_fd, F_SETFL, flags | O_NONBLOCK);
            if ret < 0 {
        Err(OsError::from_errno())
    } else {
        Ok(())
    }
        }
    }
    
    impl Drop for Pipe {
        fn drop(&mut self) -> () {
            self.close_read();
            self.close_write();
        }
    }
    
    #[derive(Clone)]
    enum Stdio {
        Inherit,
        Piped,
        Null,
        Fd(i64),
    }
    
    #[derive(Clone)]
    struct PipedCommand {
        program: String,
        args: Vec<String>,
        env: Map<String, String>,
        cwd: Option<String>,
        stdin_cfg: Stdio,
        stdout_cfg: Stdio,
        stderr_cfg: Stdio,
    }
    
    pub fn piped_command(program: &str) -> PipedCommand {
        PipedCommand { program: (program).to_string(), args: Vec::new(), env: BTreeMap::new(), cwd: Option::None, stdin_cfg: Stdio::Inherit, stdout_cfg: Stdio::Inherit, stderr_cfg: Stdio::Inherit }
    }
    
    impl PipedCommand {
        fn arg(&mut self, a: &str) -> &mut PipedCommand {
            self.args.push((a).to_string());
            self.clone()
        }
        fn args(&mut self, a: &[&str]) -> &mut PipedCommand {
            for s in (a).clone() {
                self.args.push((s).to_string())
            }
            self.clone()
        }
        fn env(&mut self, key: &str, val: &str) -> &mut PipedCommand {
            self.env.insert((key).to_string(), (val).to_string());
            self.clone()
        }
        fn current_dir(&mut self, dir: &str) -> &mut PipedCommand {
            self.cwd = Option::Some((dir).to_string());
            self.clone()
        }
        fn stdin(&mut self, cfg: Stdio) -> &mut PipedCommand {
            self.stdin_cfg = cfg;
            self.clone()
        }
        fn stdout(&mut self, cfg: Stdio) -> &mut PipedCommand {
            self.stdout_cfg = cfg;
            self.clone()
        }
        fn stderr(&mut self, cfg: Stdio) -> &mut PipedCommand {
            self.stderr_cfg = cfg;
            self.clone()
        }
        fn spawn(&self) -> Result<PipedChild, OsError> {
            let stdin_pipe = match &self.stdin_cfg { Stdio::Piped => {
        Option::Some(pipe_create()?)
    }, _ => {
        Option::None
    } };
            let stdout_pipe = match &self.stdout_cfg { Stdio::Piped => {
        Option::Some(pipe_create()?)
    }, _ => {
        Option::None
    } };
            let stderr_pipe = match &self.stderr_cfg { Stdio::Piped => {
        Option::Some(pipe_create()?)
    }, _ => {
        Option::None
    } };
            let pid = fork();
            if pid < 0 {
        return Err(OsError::from_errno());
    };
            if pid == 0 {
        if let Option::Some(p) = &stdin_pipe {
        dup2(p.read_fd, 0);
        c_close(p.write_fd)
    };
        if let Option::Some(p) = &stdout_pipe {
        dup2(p.write_fd, 1);
        c_close(p.read_fd)
    };
        if let Option::Some(p) = &stderr_pipe {
        dup2(p.write_fd, 2);
        c_close(p.read_fd)
    };
        if let Stdio::Null = &self.stdin_cfg {
        let devnull = open_fd("/dev/null".to_string(), 0);
        dup2(devnull, 0);
        c_close(devnull)
    };
        if let Stdio::Null = &self.stdout_cfg {
        let devnull = open_fd("/dev/null".to_string(), 1);
        dup2(devnull, 1);
        c_close(devnull)
    };
        if let Option::Some(dir) = &self.cwd {
        chdir(dir.as_ptr())
    };
        for (k, v) in &self.env {
            setenv(k.as_ptr(), v.as_ptr(), 1)
        }
        exec_command(&self.program, &self.args);
        _exit(127)
    };
            let child_stdin = if let Option::Some(p) = stdin_pipe {
        p.close_read();
        Option::Some(p)
    } else {
        Option::None
    };
            let child_stdout = if let Option::Some(p) = stdout_pipe {
        p.close_write();
        Option::Some(p)
    } else {
        Option::None
    };
            let child_stderr = if let Option::Some(p) = stderr_pipe {
        p.close_write();
        Option::Some(p)
    } else {
        Option::None
    };
            Ok(PipedChild { pid: pid, stdin: child_stdin, stdout: child_stdout, stderr: child_stderr })
        }
    }
    
    #[derive(Clone)]
    struct PipedChild {
        pid: i64,
        stdin: Option<Pipe>,
        stdout: Option<Pipe>,
        stderr: Option<Pipe>,
    }
    
