    #[derive(Clone)]
    struct ProcessGroup {
        pgid: i64,
    }
    
    impl ProcessGroup {
        fn new() -> Result<ProcessGroup, OsError> {
            let pid = getpid();
            let ret = setpgid(pid, pid);
            if ret < 0 {
        Err(OsError::from_errno())
    } else {
        Ok(ProcessGroup { pgid: pid })
    }
        }
        fn add(&self, child_pid: i64) -> Result<(), OsError> {
            let ret = setpgid(child_pid, self.pgid);
            if ret < 0 {
        Err(OsError::from_errno())
    } else {
        Ok(())
    }
        }
        fn signal_all(&self, sig: i64) -> Result<(), OsError> {
            let ret = killpg(self.pgid, sig);
            if ret < 0 {
        Err(OsError::from_errno())
    } else {
        Ok(())
    }
        }
        fn terminate_all(&self) -> Result<(), OsError> {
            self.signal_all(15)
        }
        fn kill_all(&self) -> Result<(), OsError> {
            self.signal_all(9)
        }
    }
    
    #[derive(Clone)]
    struct SignalForwarder {
        child_pid: i64,
        signals: Vec<i64>,
    }
    
    pub fn signal_forwarder(child_pid: i64) -> SignalForwarder {
        SignalForwarder { child_pid: child_pid, signals: Vec::from(vec![1, 2, 3, 15]) }
    }
    
    impl SignalForwarder {
        fn add_signal(&mut self, sig: i64) -> &mut SignalForwarder {
            self.signals.push(sig);
            self.clone()
        }
        fn install(&self) -> Result<(), OsError> {
            for sig in &self.signals {
                let child = self.child_pid;
                signal_trap(*sig, move || {
        let _ = c_kill(child, *sig);
    })?
            }
            Ok(())
        }
    }
    
    #[derive(Clone)]
    struct EnvBuilder {
        vars: Map<String, String>,
        inherit: bool,
    }
    
    pub fn env_builder() -> EnvBuilder {
        EnvBuilder { vars: BTreeMap::new(), inherit: true }
    }
    
    pub fn env_builder_clean() -> EnvBuilder {
        EnvBuilder { vars: BTreeMap::new(), inherit: false }
    }
    
    impl EnvBuilder {
        fn set(&mut self, key: &str, value: &str) -> &mut EnvBuilder {
            self.vars.insert((key).to_string(), (value).to_string());
            self.clone()
        }
        fn remove(&mut self, key: &str) -> &mut EnvBuilder {
            self.vars.remove(&&(key).to_string());
            self.clone()
        }
        fn prepend_path(&mut self, dir: &str) -> &mut EnvBuilder {
            let current = match self.vars.get(&&("PATH".to_string()).to_string()) { Option::Some(value) => {
        value.clone()
    }, Option::None => {
        match std::env::var("PATH".to_string()).ok() { Option::Some(value) => {
        value
    }, Option::None => {
        ("".to_string()).to_string()
    } }
    } };
            self.vars.insert(("PATH".to_string()).to_string(), format!("{}{}", format!("{}{}", (dir).to_string(), ":".to_string()), &current));
            self.clone()
        }
        fn append_path(&mut self, dir: &str) -> &mut EnvBuilder {
            let current = match self.vars.get(&&("PATH".to_string()).to_string()) { Option::Some(value) => {
        value.clone()
    }, Option::None => {
        match std::env::var("PATH".to_string()).ok() { Option::Some(value) => {
        value
    }, Option::None => {
        ("".to_string()).to_string()
    } }
    } };
            self.vars.insert(("PATH".to_string()).to_string(), format!("{}{}", format!("{}{}", current, ":".to_string()), dir));
            self.clone()
        }
        fn build(&self) -> Map<String, String> {
            let mut env = if self.inherit {
        current_env()
    } else {
        BTreeMap::new()
    };
            for (k, v) in &self.vars {
                env.insert(k.clone(), v.clone())
            }
            env
        }
    }
    
