    static PRIO_PROCESS: () = 0;
    
    static PRIO_PGRP: () = 1;
    
    static PRIO_USER: () = 2;
    
    pub fn get_priority() -> Result<i64, OsError> {
        let p = getpriority(PRIO_PROCESS, 0);
        Ok(p)
    }
    
    pub fn set_priority(prio: i64) -> Result<(), OsError> {
        let ret = setpriority(PRIO_PROCESS, 0, prio);
        if ret < 0 {
        Err(OsError::from_errno())
    } else {
        Ok(())
    }
    }
    
    pub fn lower_priority(inc: i64) -> Result<i64, OsError> {
        let ret = nice(inc);
        if ret < 0 {
        Err(OsError::from_errno())
    } else {
        Ok(ret)
    }
    }
    
