        let mut out = String::new();
        out = format!("{}{}", out, "/* Auto-generated C header for Tangerine module */\n".to_string());
        out = format!("{}{}", format!("{}{}", format!("{}{}", out, "#ifndef TANGERINE_".to_string()), &_header_guard(module_path)), "_H\n".to_string());
