    use crate::util::to_float;
    
    pub fn CAP_NET() -> String {
        "NetCap".to_string()
    }
    
    pub fn CAP_FS() -> String {
        "FsCap".to_string()
    }
    
    pub fn CAP_FS_READ() -> String {
        "FsReadCap".to_string()
    }
    
    pub fn CAP_PROC() -> String {
        "ProcCap".to_string()
    }
    
    pub fn CAP_ENV() -> String {
        "EnvCap".to_string()
    }
    
