    pub fn type_size(ty: &Type, layout: &Map<i64, i64>) -> i64 {
        match ty { Type::Unit => {
        0
    }, Type::Bool => {
        1
    }, Type::Char => {
        4
    }, Type::Int => {
        8
    }, Type::Float => {
        8
    }, Type::String => {
        24
    }, Type::Never => {
        0
    }, Type::Ref(_, _) => {
        8
    }, Type::RefMut(_, _) => {
        8
    }, Type::Owned(_) => {
        8
    }, Type::Tuple(fields) => {
        let mut total = 0;
        let mut max_align = 1;
        for f in (fields).clone() {
            let sz = type_size(f, layout);
            let align = type_align(f);
            if align > max_align {
        max_align = align;
    };
            let rem = total % align;
            if rem != 0 {
        total = total + align - rem;
    };
            total = total + sz;
        }
        let rem = total % max_align;
        if rem != 0 {
        total = total + max_align - rem;
    };
        total
    }, Type::Array(elem, count) => {
        type_size(elem, layout) * count
    }, Type::Slice(_) => {
        16
    }, Type::Named(tid, _) => {
        match layout.get(&tid.id) { Option::Some(sz) => {
        sz
    }, Option::None => {
        8
    } }
    }, Type::Function(_, _) => {
        8
    }, Type::Var(_) => {
        8
    }, Type::Error => {
        0
    } }
    }
    
    pub fn type_align(ty: &Type) -> i64 {
        match ty { Type::Unit => {
        1
    }, Type::Bool => {
        1
    }, Type::Char => {
        4
    }, _ => {
        8
    } }
    }
    
    pub fn align_up_int(v: i64, align: i64) -> i64 {
        v + align - 1 / align * align
    }
    
    pub fn build_type_layout(types: &Vec<MirTypeDef>) -> Map<i64, i64> {
        let mut layout = BTreeMap::new();
        for td in (types).clone() {
            layout.insert(td.id.id, 0)
        }
        for td in (types).clone() {
            let sz = match td.kind { MirTypeDefKind::Struct(fields) => {
        let mut total = 0;
        let mut max_align = 1;
        for f in (fields).clone() {
            let fsz = type_size(&f.ty, &layout);
            let fa = type_align(&f.ty);
            if fa > max_align {
        max_align = fa;
    };
            let rem = total % fa;
            if rem != 0 {
        total = total + fa - rem;
    };
            total = total + fsz;
        }
        let rem = total % max_align;
        if rem != 0 {
        total = total + max_align - rem;
    };
        total
    }, MirTypeDefKind::Enum(variants) => {
        let mut max_payload = 0;
        for v in (variants).clone() {
            let mut payload = 0;
            for fty in (v.fields).clone() {
                payload = payload + type_size(fty, &layout);
            }
            if payload > max_payload {
        max_payload = payload;
    }
        }
        8 + max_payload
    } };
            layout.insert(td.id.id, sz)
        }
        layout
    }
    
