    #[derive(Clone)]
    struct RegAllocState {
        free_regs: Vec<PhysReg>,
        used_callee: Set<i64>,
        assignments: Map<i64, VarLoc>,
        arch: Arch,
    }
    
    pub fn reg_alloc_new(arch: Arch) -> RegAllocState {
        RegAllocState { free_regs: allocatable_regs(arch), used_callee: Set::new(), assignments: BTreeMap::new(), arch: arch }
    }
    
    pub fn alloc_reg(state: &mut RegAllocState) -> Option<PhysReg> {
        if state.free_regs.is_empty() {
        return Option::None;
    };
        match state.free_regs.pop() { Option::Some(r) => {
        if phys_is_callee_saved(r) {
        state.used_callee.insert(phys_reg_id(r))
    };
        Option::Some(r)
    }, Option::None => {
        Option::None
    } }
    }
    
    pub fn alloc_reg_or_spill(state: &mut RegAllocState, ctx: &mut CodegenCtx, frame: &mut FrameInfo) -> PhysReg {
        match alloc_reg(state) { Option::Some(r) => {
        r
    }, Option::None => {
        let mut spill_victim_id = -1;
        let mut spill_reg = scratch_reg(state.arch);
        for entry in (state.assignments).clone() {
            match entry.1 { VarLoc::Register(r) => {
        spill_victim_id = entry.0;
        spill_reg = r;
        break;
    }, _ => {
        ()
    } }
        }
        if spill_victim_id >= 0 {
        let fp = fp_reg(state.arch);
        frame.spill_offset = frame.spill_offset - 8;
        let offset = frame.spill_offset;
        emit_store_mem(ctx, fp, offset, spill_reg);
        state.assignments.insert(spill_victim_id, VarLoc::Spilled(offset));
        frame.local_offsets.insert(spill_victim_id, offset)
    };
        spill_reg
    } }
    }
    
    pub fn reload_spill(ctx: &mut CodegenCtx, sp: PhysReg, offset: i32, dst: PhysReg) -> () {
        emit_load_mem(ctx, dst, sp, offset);
    }
    
    pub fn free_reg(state: &mut RegAllocState, r: PhysReg) -> () {
        state.free_regs.push(r);
    }
    
    pub fn collect_saved_regs(state: &RegAllocState, arch: Arch) -> Vec<PhysReg> {
        let mut saved = Vec::new();
        match arch { Arch::X86_64 => {
        if state.used_callee.contains(((x64_code(X64::RBX)) as i64)) {
        saved.push(PhysReg::X64Reg(X64::RBX))
    };
        if state.used_callee.contains(((x64_code(X64::R12)) as i64)) {
        saved.push(PhysReg::X64Reg(X64::R12))
    };
        if state.used_callee.contains(((x64_code(X64::R13)) as i64)) {
        saved.push(PhysReg::X64Reg(X64::R13))
    };
        if state.used_callee.contains(((x64_code(X64::R14)) as i64)) {
        saved.push(PhysReg::X64Reg(X64::R14))
    };
        if state.used_callee.contains(((x64_code(X64::R15)) as i64)) {
        saved.push(PhysReg::X64Reg(X64::R15))
    }
    }, Arch::AArch64 => {
        if state.used_callee.contains(((a64_code(A64::X19)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X19))
    };
        if state.used_callee.contains(((a64_code(A64::X20)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X20))
    };
        if state.used_callee.contains(((a64_code(A64::X21)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X21))
    };
        if state.used_callee.contains(((a64_code(A64::X22)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X22))
    };
        if state.used_callee.contains(((a64_code(A64::X23)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X23))
    };
        if state.used_callee.contains(((a64_code(A64::X24)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X24))
    };
        if state.used_callee.contains(((a64_code(A64::X25)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X25))
    };
        if state.used_callee.contains(((a64_code(A64::X26)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X26))
    };
        if state.used_callee.contains(((a64_code(A64::X27)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X27))
    };
        if state.used_callee.contains(((a64_code(A64::X28)) as i64)) {
        saved.push(PhysReg::A64Reg(A64::X28))
    }
    } };
        saved
    }
    
    pub fn saved_reg_bytes(saved: &Vec<PhysReg>) -> i64 {
        let mut count = 0;
        for _ in (*saved).clone() {
            count = count + 1;
        }
        count * 8
    }
    
    pub fn allocate_locals(func: &MirFunction, arch: Arch, layout: &Map<i64, i64>) -> (Map<i64, VarLoc>, FrameInfo) {
        let mut ra = reg_alloc_new(arch);
        let mut local_offsets = BTreeMap::new();
        let mut var_locs = BTreeMap::new();
        let mut spill_off = 0;
        for local in (func.locals).clone() {
            let sz = type_size(&local.ty, layout);
            if sz == 0 {
        var_locs.insert(local.id.id, VarLoc::Stack(0));
        continue;
    };
            match alloc_reg(&mut ra) { Option::Some(r) => {
        var_locs.insert(local.id.id, VarLoc::Register(r))
    }, Option::None => {
        let aligned_sz = align_up_int(sz, 8);
        spill_off = spill_off - ((aligned_sz) as i32);
        var_locs.insert(local.id.id, VarLoc::Spilled(spill_off));
        local_offsets.insert(local.id.id, spill_off)
    } }
        }
        let mut arg_idx = 0;
        for param in (func.params).clone() {
            let sz = type_size(&param.ty, layout);
            if sz == 0 {
        var_locs.insert(param.id.id, VarLoc::Stack(0))
    } else {
        match alloc_reg(&mut ra) { Option::Some(r) => {
        var_locs.insert(param.id.id, VarLoc::Register(r))
    }, Option::None => {
        let aligned_sz = align_up_int(sz, 8);
        spill_off = spill_off - ((aligned_sz) as i32);
        var_locs.insert(param.id.id, VarLoc::Spilled(spill_off))
    } }
    };
            arg_idx = arg_idx + 1;
        }
        let saved = collect_saved_regs(&ra, arch);
        let spill_bytes = if spill_off < 0 {
        ((-spill_off) as i64)
    } else {
        0
    };
        let save_bytes = saved_reg_bytes(&saved);
        let raw_size = spill_bytes + save_bytes;
        let stack_size = align_up_int(raw_size, 16);
        let frame = FrameInfo { stack_size: stack_size, local_offsets: local_offsets, spill_offset: spill_off, saved_regs: saved };
        (var_locs, frame)
    }
    
    pub fn codegen_new(target: AsmTarget) -> CodegenCtx {
        CodegenCtx { target: target, text: buf_new(), data: buf_new(), rodata: buf_new(), bss_size: 0, bss_symbols: Vec::new(), string_pool: BTreeMap::new(), string_counter: 0, fn_counter: 0, type_layout: BTreeMap::new() }
    }
    
    pub fn intern_string(ctx: &mut CodegenCtx, s: &String) -> String {
        match ctx.string_pool.get(&s) { Option::Some(label) => {
        return label;
    }, Option::None => {
        ()
    } };
        let label = format!("{}{}", ".Lstr.".to_string(), (ctx.string_counter).to_string());
        ctx.string_counter = ctx.string_counter + 1;
        ctx.string_pool.insert(s.clone(), label.clone());
        def_label(&mut ctx.rodata, label.clone());
        for byte in (s.bytes()).clone() {
            emit8(&mut ctx.rodata, byte)
        }
        emit8(&mut ctx.rodata, 0);
        label
    }
    
