    pub fn emit_load_mem(ctx: &mut CodegenCtx, dst: PhysReg, base: PhysReg, offset: i32) -> () {
        match dst { PhysReg::X64Reg(d) => {
        match base { PhysReg::X64Reg(b) => {
        x64_mov_rm(&mut ctx.text, d, b, offset)
    }, _ => {
        panic!("emit_load_mem: mixed architectures".to_string())
    } }
    }, PhysReg::A64Reg(d) => {
        match base { PhysReg::A64Reg(b) => {
        if offset >= 0 && offset % 8 == 0 && offset < 32768 {
        a64_ldr(&mut ctx.text, d, b, ((offset) as u32))
    } else {
        a64_ldur(&mut ctx.text, d, b, offset)
    }
    }, _ => {
        panic!("emit_load_mem: mixed architectures".to_string())
    } }
    } };
    }
    
    pub fn emit_store_mem(ctx: &mut CodegenCtx, base: PhysReg, offset: i32, src: PhysReg) -> () {
        match base { PhysReg::X64Reg(b) => {
        match src { PhysReg::X64Reg(s) => {
        x64_mov_mr(&mut ctx.text, b, offset, s)
    }, _ => {
        panic!("emit_store_mem: mixed architectures".to_string())
    } }
    }, PhysReg::A64Reg(b) => {
        match src { PhysReg::A64Reg(s) => {
        if offset >= 0 && offset % 8 == 0 && offset < 32768 {
        a64_str(&mut ctx.text, s, b, ((offset) as u32))
    } else {
        a64_stur(&mut ctx.text, s, b, offset)
    }
    }, _ => {
        panic!("emit_store_mem: mixed architectures".to_string())
    } }
    } };
    }
    
