    pub fn sort_signals(signals: &mut Vec<Signal>) -> () {
        signals.sort_by(move |a, b| {
        let ka = signal_kind_ordinal(a.kind);
        let kb = signal_kind_ordinal(b.kind);
        if ka != kb {
        ka < kb
    } else if (a.locations.len() as i64) > 0 && (b.locations.len() as i64) > 0 {
        let la = a.locations[(0) as usize].clone();
        let lb = b.locations[(0) as usize].clone();
        if la.file != lb.file {
        la.file < lb.file
    } else if la.start_line != lb.start_line {
        la.start_line < lb.start_line
    } else {
        la.start_col < lb.start_col
    }
    } else {
        false
    }
    });
    }
    
    pub fn signal_kind_ordinal(k: SignalKind) -> i64 {
        match k { SignalKind::CF1_UnreachableBranch => {
        0
    }, SignalKind::CF2_NonExhaustiveMatch => {
        1
    }, SignalKind::CF3_PanicUnreachableExit => {
        2
    }, SignalKind::CF4_ConstantReturnDominance => {
        3
    }, SignalKind::DF1_UnusedParameter => {
        4
    }, SignalKind::DF2_OutputIndependentOfInputs => {
        5
    }, SignalKind::DF3_DeadAssignment => {
        6
    }, SignalKind::DF4_AllBranchesReturnSameLiteral => {
        7
    }, SignalKind::EH1_IgnoredResultWithoutJustification => {
        8
    }, SignalKind::EH2_CatchAllWithoutAction => {
        9
    }, SignalKind::EH3_BroadExceptionBoundarySwallowing => {
        10
    }, SignalKind::CV1_UnexecutedPublicBranch => {
        11
    }, SignalKind::CV2_CoverageBelowThreshold => {
        12
    }, SignalKind::CP1_CapabilityDrift => {
        13
    }, SignalKind::CP2_UnsafeBlockWithoutReason => {
        14
    }, SignalKind::CP3_TaintedFFIValueUsedWithoutValidation => {
        15
    }, SignalKind::FT1_FutureBlockInEnabledFeature => {
        16
    }, SignalKind::FT2_CfgFeatureEnabledButIncomplete => {
        17
    } }
    }
    
