    pub fn detect_df1(params: &Vec<ParamInfo>, def_use: &DefUseGraph) -> Option<Signal> {
        let mut unused_count = 0;
        let mut locs = Vec::new();
        for p in (params).clone() {
            if p.name.starts_with("_".to_string()) || p.has_unused_ok {
        continue;
    };
            if p.is_context_param {
        continue;
    };
            let mut has_use = false;
            for link in &def_use.links {
                let def = &def_use.definitions[(link.def_index) as usize].clone();
                if def.local_id == p.local_id {
        has_use = true;
        break;
    }
            }
            if !has_use {
        unused_count = unused_count + 1;
        locs.push(p.span)
    }
        }
        if unused_count > 0 {
        let params_sev = sev_count_params(SignalKind::DF1_UnusedParameter);
        Option::Some(Signal { kind: SignalKind::DF1_UnusedParameter, severity: sev_count(unused_count, params_sev.n0, params_sev.n1), count: unused_count, suppressed: false, penalty: 0.0, locations: locs, details: BTreeMap::new() })
    } else {
        Option::None
    }
    }
    
