    pub fn reachable_to_sink(graph: &DependencyGraph, start: i64, sinks: &Vec<i64>) -> bool {
        let mut visited = Set::new();
        let mut stack = Vec::new();
        stack.push(start);
        while !stack.is_empty() {
            let node = stack.pop().unwrap();
            if sinks.contains(node) {
        return true;
    };
            if !visited.contains(node) {
        visited.insert(node);
        for edge in &graph.edges {
            if edge.from_local == node {
        stack.push(edge.to_local)
    }
        }
    }
        }
        false
    }
    
