    pub fn detect_df4(branches: &Vec<BranchReturnInfo>) -> Option<Signal> {
        let mut bad_count = 0;
        let mut locs = Vec::new();
        for br in (branches).clone() {
            if br.branch_count >= 2 && (br.return_values.len() as i64) >= 2 {
        let first = br.return_values[(0) as usize].clone().clone();
        let mut all_same = true;
        for val in (br.return_values).clone() {
            if val != first {
        all_same = false;
        break;
    }
        }
        if all_same {
        bad_count = bad_count + 1;
        locs.push(br.span)
    }
    }
        }
        if bad_count > 0 {
        Option::Some(Signal { kind: SignalKind::DF4_AllBranchesReturnSameLiteral, severity: sev_binary(), count: bad_count, suppressed: false, penalty: 0.0, locations: locs, details: BTreeMap::new() })
    } else {
        Option::None
    }
    }
    
