    pub fn render_struct_html(s: &DocStruct) -> String {
        let mut html = format!("{}{}", format!("{}{}", "  <section id=\"struct-".to_string(), s.name), "\" class=\"item struct\">\n".to_string());
        html = format!("{}{}", format!("{}{}", html, "    <h2>Struct <code>".to_string()), s.name);
        if !s.type_params.is_empty() {
        html = format!("{}{}", format!("{}{}", format!("{}{}", html, "[".to_string()), s.type_params.join(", ".to_string())), "]".to_string());
    };
        html = format!("{}{}", html, "</code></h2>\n".to_string());
        if !s.doc_comment.is_empty() {
        html = format!("{}{}", format!("{}{}", format!("{}{}", html, "    <div class=\"doc\">".to_string()), html_escape(s.doc_comment.clone())), "</div>\n".to_string());
    };
        if !s.fields.is_empty() {
        html = format!("{}{}", html, "    <h3>Fields</h3>\n    <table class=\"fields\">\n".to_string());
        html = format!("{}{}", html, "      <tr><th>Name</th><th>Type</th><th>Description</th></tr>\n".to_string());
        for f in (s.fields).clone() {
            html = format!("{}{}", format!("{}{}", format!("{}{}", html, "      <tr><td><code>".to_string()), f.name), "</code></td>".to_string());
            html = format!("{}{}", format!("{}{}", format!("{}{}", html, "<td><code>".to_string()), html_escape(f.type_str.clone())), "</code></td>".to_string());
            html = format!("{}{}", format!("{}{}", format!("{}{}", html, "<td>".to_string()), html_escape(f.doc_comment.clone())), "</td></tr>\n".to_string());
        }
        html = format!("{}{}", html, "    </table>\n".to_string());
    };
        html = format!("{}{}", html, "  </section>\n\n".to_string());
        html
    }
    
