    pub fn cmd_test(argv: Vec<String>) -> i64 {
        let test_files = match parse_args(argv) { Result::Ok(o) => {
        if o.input_files.is_empty() {
        match load_project(".".to_string()) { Result::Ok(project) => {
        project.sources.clone()
    }, Result::Err(_) => {
        find_tg_files(".".to_string())
    } }
    } else {
        o.input_files.clone()
    }
    }, Result::Err(e) => {
        if e == "help".to_string() {
        println!("{}", "Usage: tg test [OPTIONS] [FILES]...".to_string());
        println!("{}", "Discover and run @test functions".to_string());
        return 0;
    } else if e == "No input files".to_string() {
        match load_project(".".to_string()) { Result::Ok(project) => {
        project.sources.clone()
    }, Result::Err(_) => {
        find_tg_files(".".to_string())
    } }
    } else {
        eprintln!("{}", format!("{}{}", "Error: ".to_string(), e));
        return 1;
    }
    } };
        let mut total = 0;
        let mut passed = 0;
        let mut failed = 0;
        let mut fail_names = Vec::new();
        let opts = default_options();
        for file in (test_files).clone() {
            let source = match std::fs::read_to_string(file.clone()).map_err(|e| e.to_string()) { Result::Ok(content) => {
        content
    }, Result::Err(_) => {
        continue;
    } };
            let lex_result = tokenize(source);
            let (ast, parse_diags) = parse(lex_result);
            if diag_has_errors(&parse_diags) {
        continue;
    };
            for item in (ast.items).clone() {
                let mut is_test = false;
                for attr in (item.attrs).clone() {
                    if attr.name == "test".to_string() {
        is_test = true;
    }
                }
                if is_test {
        match item.kind { ItemKind::ItemFunction(func_decl) => {
        total = total + 1;
        let test_name = format!("{}{}", format!("{}{}", file.clone(), "::".to_string()), func_decl.name.clone());
        match compile_and_run_test(&opts, file.clone(), &func_decl) { Result::Ok(_) => {
        passed = passed + 1;
        println!("{}", format!("{}{}", "  PASS  ".to_string(), test_name))
    }, Result::Err(e) => {
        failed = failed + 1;
        fail_names.push(test_name.clone());
        println!("{}", format!("{}{}", format!("{}{}", format!("{}{}", "  FAIL  ".to_string(), test_name), ": ".to_string()), e))
    } }
    }, _ => {
        ()
    } }
    }
            }
        }
        println!("{}", "".to_string());
        println!("{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "test result: ".to_string(), if failed == 0 {
        "ok".to_string()
    } else {
        "FAILED".to_string()
    }), ". ".to_string()), (passed).to_string()), " passed; ".to_string()), (failed).to_string()), " failed; ".to_string()), (total).to_string()), " total".to_string()));
        if !fail_names.is_empty() {
        println!("{}", "".to_string());
        println!("{}", "failures:".to_string());
        for name in (fail_names).clone() {
            println!("{}", format!("{}{}", "    ".to_string(), name))
        }
    };
        if failed > 0 {
        1
    } else {
        0
    }
    }
    
    pub fn compile_and_run_test(opts: &CompilerOptions, path: String, func: &FunctionDecl) -> Result<(), String> {
        match compile_file(opts, path) { Result::Ok(output_path) => {
        let cmd = format!("{}{}", format!("{}{}", output_path, " --run-test ".to_string()), func.name.clone());
        let exit_code = bootstrap_call_system(cmd);
        if exit_code == 0 {
        Ok(())
    } else {
        Err(format!("{}{}", "test exited with code ".to_string(), (exit_code).to_string()))
    }
    }, Result::Err(e) => {
        Err(format!("{}{}", "compilation failed: ".to_string(), e))
    } }
    }
    
