    pub fn cmd_fmt(argv: Vec<String>) -> i64 {
        let mut check_only = false;
        let mut files = Vec::new();
        let mut config = default_format_config();
        let mut i = 1;
        while i < (argv.len() as i64) {
            let arg = argv[(i) as usize].clone();
            if arg == "--check".to_string() {
        check_only = true;
    } else if arg == "--indent".to_string() {
        i = i + 1;
        if i < (argv.len() as i64) {
        config.indent_width = argv[(i) as usize].clone().parse_uint().unwrap_or(2);
    }
    } else if arg == "--line-width".to_string() {
        i = i + 1;
        if i < (argv.len() as i64) {
        config.max_line_width = argv[(i) as usize].clone().parse_uint().unwrap_or(100);
    }
    } else if arg == "-h".to_string() || arg == "--help".to_string() {
        println!("{}", "Usage: tg fmt [OPTIONS] [FILES]...".to_string());
        println!("{}", "Format Tangerine source files".to_string());
        println!("{}", "".to_string());
        println!("{}", "Options:".to_string());
        println!("{}", "  --check          Check formatting without writing".to_string());
        println!("{}", "  --indent <N>     Indentation width (default: 2)".to_string());
        println!("{}", "  --line-width <N> Maximum line width (default: 100)".to_string());
        return 0;
    } else if !arg.starts_with("-".to_string()) {
        files.push(arg.clone())
    };
            i = i + 1;
        }
        if files.is_empty() {
        files = find_tg_files(".".to_string());
    };
        let mut exit_code = 0;
        let mut formatted_count = 0;
        for file in (files).clone() {
            if check_only {
        match format_check(file.clone(), &config) { Result::Ok(needs_format) => {
        if needs_format {
        println!("{}", format!("{}{}", "Would reformat: ".to_string(), file));
        exit_code = 1;
    }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", format!("{}{}", format!("{}{}", "Error: ".to_string(), file), ": ".to_string()), e));
        exit_code = 1;
    } }
    } else {
        match format_file(file.clone(), &config) { Result::Ok(changed) => {
        if changed {
        formatted_count = formatted_count + 1;
        println!("{}", format!("{}{}", "Formatted: ".to_string(), file))
    }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", format!("{}{}", format!("{}{}", "Error: ".to_string(), file), ": ".to_string()), e));
        exit_code = 1;
    } }
    }
        }
        if !check_only && formatted_count > 0 {
        println!("{}", format!("{}{}", (formatted_count).to_string(), " file(s) formatted".to_string()))
    };
        exit_code
    }
    
    pub fn cmd_lint(argv: Vec<String>) -> i64 {
        let mut files = Vec::new();
        let mut config = default_lint_config();
        let mut i = 1;
        while i < (argv.len() as i64) {
            let arg = argv[(i) as usize].clone();
            if arg == "--deny".to_string() {
        i = i + 1;
        if i < (argv.len() as i64) {
        config.denied.push(argv[(i) as usize].clone().clone())
    }
    } else if arg == "--allow".to_string() {
        i = i + 1;
        if i < (argv.len() as i64) {
        config.allowed.push(argv[(i) as usize].clone().clone())
    }
    } else if arg == "--warn".to_string() {
        i = i + 1;
        if i < (argv.len() as i64) {
        config.warned.push(argv[(i) as usize].clone().clone())
    }
    } else if arg == "--json".to_string() {
        config.json_output = true;
    } else if arg == "-h".to_string() || arg == "--help".to_string() {
        println!("{}", "Usage: tg lint [OPTIONS] [FILES]...".to_string());
        println!("{}", "Run linter on Tangerine source files".to_string());
        println!("{}", "".to_string());
        println!("{}", "Options:".to_string());
        println!("{}", "  --deny <LINT>    Deny a lint (error)".to_string());
        println!("{}", "  --allow <LINT>   Allow a lint (suppress)".to_string());
        println!("{}", "  --warn <LINT>    Warn on a lint".to_string());
        println!("{}", "  --json           Output diagnostics as JSON".to_string());
        return 0;
    } else if !arg.starts_with("-".to_string()) {
        files.push(arg.clone())
    };
            i = i + 1;
        }
        if files.is_empty() {
        files = find_tg_files(".".to_string());
    };
        let mut total_warnings = 0;
        let mut total_errors = 0;
        for file in (files).clone() {
            match lint_file(file.clone(), &config) { Result::Ok(diagnostics) => {
        for diag in (diagnostics).clone() {
            match diag.level { LintLevel::Error => {
        total_errors = total_errors + 1;
        eprintln!("{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "error[".to_string(), diag.lint_name), "]: ".to_string()), diag.message), " (".to_string()), file), ":".to_string()), (diag.line).to_string()), ")".to_string()))
    }, LintLevel::Warning => {
        total_warnings = total_warnings + 1;
        eprintln!("{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "warning[".to_string(), diag.lint_name), "]: ".to_string()), diag.message), " (".to_string()), file), ":".to_string()), (diag.line).to_string()), ")".to_string()))
    }, LintLevel::Info => {
        eprintln!("{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "info[".to_string(), diag.lint_name), "]: ".to_string()), diag.message), " (".to_string()), file), ":".to_string()), (diag.line).to_string()), ")".to_string()))
    } }
        }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", format!("{}{}", format!("{}{}", "Error linting ".to_string(), file), ": ".to_string()), e));
        total_errors = total_errors + 1;
    } }
        }
        if total_errors > 0 || total_warnings > 0 {
        eprintln!("{}", format!("{}{}", format!("{}{}", format!("{}{}", (total_errors).to_string(), " error(s), ".to_string()), (total_warnings).to_string()), " warning(s)".to_string()))
    };
        if total_errors > 0 {
        1
    } else {
        0
    }
    }
    
    pub fn cmd_doc(argv: Vec<String>) -> i64 {
        let mut files = Vec::new();
        let mut config = default_doc_config();
        let mut i = 1;
        while i < (argv.len() as i64) {
            let arg = argv[(i) as usize].clone();
            if arg == "--output".to_string() || arg == "-o".to_string() {
        i = i + 1;
        if i < (argv.len() as i64) {
        config.output_dir = argv[(i) as usize].clone().clone();
    }
    } else if arg == "--format".to_string() {
        i = i + 1;
        if i < (argv.len() as i64) {
        if argv[(i) as usize].clone() == "html".to_string() {
        config.format = DocFormat::Html;
    } else if argv[(i) as usize].clone() == "markdown".to_string() || argv[(i) as usize].clone() == "md".to_string() {
        config.format = DocFormat::Markdown;
    }
    }
    } else if arg == "--private".to_string() {
        config.include_private = true;
    } else if arg == "-h".to_string() || arg == "--help".to_string() {
        println!("{}", "Usage: tg doc [OPTIONS] [FILES]...".to_string());
        println!("{}", "Generate documentation".to_string());
        println!("{}", "".to_string());
        println!("{}", "Options:".to_string());
        println!("{}", "  -o, --output <DIR>  Output directory (default: docs/api)".to_string());
        println!("{}", "  --format <FMT>      Output format: html, markdown (default: html)".to_string());
        println!("{}", "  --private           Include private items".to_string());
        return 0;
    } else if !arg.starts_with("-".to_string()) {
        files.push(arg.clone())
    };
            i = i + 1;
        }
        if files.is_empty() {
        files = find_tg_files(".".to_string());
    };
        match generate_docs(files, &config) { Result::Ok(count) => {
        println!("{}", format!("{}{}", format!("{}{}", format!("{}{}", "Generated documentation for ".to_string(), (count).to_string()), " item(s) in ".to_string()), config.output_dir));
        0
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Error generating docs: ".to_string(), e));
        1
    } }
    }
    
    pub fn cmd_bench(argv: Vec<String>) -> i64 {
        let bench_files = if (argv.len() as i64) > 1 && !argv[(1) as usize].clone().starts_with("-".to_string()) {
        let mut files = Vec::new();
        let mut i = 1;
        while i < (argv.len() as i64) {
            if !argv[(i) as usize].clone().starts_with("-".to_string()) {
        files.push(argv[(i) as usize].clone().clone())
    };
            i = i + 1;
        }
        files
    } else {
        match load_project(".".to_string()) { Result::Ok(project) => {
        project.sources.clone()
    }, Result::Err(_) => {
        find_bench_files(".".to_string())
    } }
    };
        if bench_files.is_empty() {
        println!("{}", "No benchmark files found.".to_string());
        return 0;
    };
        let opts = default_options();
        let mut total = 0;
        let mut ok_count = 0;
        for file in (bench_files).clone() {
            let source = match std::fs::read_to_string(file.clone()).map_err(|e| e.to_string()) { Result::Ok(content) => {
        content
    }, Result::Err(_) => {
        continue;
    } };
            let lex_result = tokenize(source);
            let (ast, parse_diags) = parse(lex_result);
            if diag_has_errors(&parse_diags) {
        continue;
    };
            let cases = extract_bench_functions(&ast, file.clone());
            for bench in (cases).clone() {
                total = total + 1;
                match compile_file(&opts, file.clone()) { Result::Ok(output_path) => {
        let cmd = format!("{}{}", format!("{}{}", output_path, " --run-bench ".to_string()), bench.name.clone());
        let exit_code = bootstrap_call_system(cmd);
        if exit_code == 0 {
        ok_count = ok_count + 1;
        println!("{}", format!("{}{}", format!("{}{}", "  bench ".to_string(), bench.name), " ... ok".to_string()))
    } else {
        println!("{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "  bench ".to_string(), bench.name), " ... FAILED (exit ".to_string()), (exit_code).to_string()), ")".to_string()))
    }
    }, Result::Err(e) => {
        println!("{}", format!("{}{}", format!("{}{}", format!("{}{}", "  bench ".to_string(), bench.name), " ... COMPILE ERROR: ".to_string()), e))
    } }
            }
        }
        println!("{}", "".to_string());
        println!("{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "bench result: ".to_string(), (ok_count).to_string()), "/".to_string()), (total).to_string()), " ok".to_string()));
        if ok_count < total {
        1
    } else {
        0
    }
    }
    
    pub fn find_bench_files(dir: String) -> Vec<String> {
        let mut files = Vec::new();
        let entries = match std::fs::read_dir(dir) { Result::Ok(entries) => {
        entries
    }, Result::Err(_) => {
        return files;
    } };
        for entry in (entries).clone() {
            if entry.is_dir && !entry.name.starts_with(".".to_string()) {
        let sub = find_bench_files(entry.path.clone());
        for f in (sub).clone() {
            files.push(f)
        }
    } else if entry.name.ends_with("_bench.tg".to_string()) || entry.name.starts_with("bench_".to_string()) {
        files.push(entry.path.clone())
    } else if entry.name.ends_with(".tg".to_string()) {
        match std::fs::read_to_string(entry.path.clone()).map_err(|e| e.to_string()) { Result::Ok(content) => {
        if content.contains("#[bench]".to_string()) {
        files.push(entry.path.clone())
    }
    }, Result::Err(_) => {
        ()
    } }
    }
        }
        files
    }
    
    pub fn extract_bench_functions(ast: &Program, file: String) -> Vec<BenchCase> {
        let mut cases = Vec::new();
        for item in (ast.items).clone() {
            let mut is_bench = false;
            for attr in (item.attrs).clone() {
                if attr.name == "bench".to_string() {
        is_bench = true;
    }
            }
            if is_bench {
        match item.kind { ItemKind::ItemFunction(func_decl) => {
        cases.push(BenchCase { name: func_decl.name.clone(), func: Box::new(move || {
        ()
    }), setup: Option::None, teardown: Option::None, iterations: Option::None, warmup_iterations: 3, input_size: Option::None })
    }, _ => {
        ()
    } }
    }
        }
        cases
    }
    
