    #[derive(Clone)]
    struct IncrementalCache {
        entries: Map<String, CacheEntry>,
        cache_dir: String,
    }
    
    #[derive(Clone)]
    struct CacheEntry {
        source_hash: String,
        mir_hash: String,
        timestamp: i64,
    }
    
    pub fn cache_new(dir: String) -> IncrementalCache {
        IncrementalCache { entries: BTreeMap::new(), cache_dir: dir }
    }
    
    pub fn is_stale(cache: &IncrementalCache, path: String, source: String) -> bool {
        match cache.entries.get(&path) { Option::Some(entry) => {
        let current_hash = (fnv1a_hash(source)).to_string();
        entry.source_hash != current_hash
    }, Option::None => {
        true
    } }
    }
    
    pub fn update_cache(cache: &mut IncrementalCache, path: String, source: String, mir_hash: String) -> () {
        let source_hash = (fnv1a_hash(source)).to_string();
        cache.entries.insert(path, CacheEntry { source_hash: source_hash, mir_hash: mir_hash, timestamp: current_time() });
    }
    
    pub fn current_time() -> i64 {
        let now = std::time::SystemTime::now();
        ((now.tv.tv_sec) as i64)
    }
    
    pub fn bootstrap_call_system(cmd: String) -> i64 {
        let mut command = std::process::Command::new(("sh".to_string()).to_string());
        command.arg(("-c".to_string()).to_string());
        command.arg(cmd);
        match command.status() { Result::Ok(status) => {
        status.code
    }, Result::Err(_) => {
        127
    } }
    }
    
    pub fn load_project(path: String) -> Result<Project, String> {
        let manifest_path = if path.ends_with("Tangerine.toml".to_string()) {
        path.clone()
    } else {
        format!("{}{}", path.clone(), "/Tangerine.toml".to_string())
    };
        match std::fs::read_to_string(manifest_path.clone()).map_err(|e| e.to_string()) { Result::Ok(content) => {
        let mut name = "untitled".to_string();
        let mut version = "0.0.0".to_string();
        let mut sources = Vec::new();
        let mut deps = Vec::new();
        let mut output_dir = "build".to_string();
        let mut section = "".to_string();
        let mut in_sources_array = false;
        for line in (content.lines().map(str::to_string).collect::<Vec<_>>()).clone() {
            let trimmed = line.trim().to_string();
            if trimmed.is_empty() || trimmed.starts_with("#".to_string()) {
        continue;
    };
            if trimmed.starts_with("[".to_string()) && trimmed.ends_with("]".to_string()) {
        section = trimmed.slice(1, (trimmed.len() as i64) - 1);
        in_sources_array = false;
        continue;
    };
            if in_sources_array {
        if trimmed.starts_with("]".to_string()) {
        in_sources_array = false;
        continue;
    };
        let mut entry = (trimmed).to_string();
        if entry.ends_with(",".to_string()) {
        entry = entry.slice(0, (entry.len() as i64) - 1);
    };
        entry = entry.trim().to_string();
        let mut cleaned = "".to_string();
        let mut i = 0;
        while i < (entry.len() as i64) {
            let ch = entry.chars().nth((i) as usize).unwrap();
            if ch != '\"' {
        cleaned = format!("{}{}", cleaned, (ch).to_string());
    };
            i = i + 1;
        }
        entry = cleaned.trim().to_string();
        if !entry.is_empty() {
        sources.push((entry).to_string())
    };
        continue;
    };
            let parts = trimmed.split("=".to_string()).map(str::to_string).collect::<Vec<_>>();
            if (parts.len() as i64) >= 2 {
        let key = parts[(0) as usize].clone().trim().to_string();
        let val = parts[(1) as usize].clone().trim().to_string();
        if section == "project".to_string() {
        if key == "name".to_string() {
        name = (val.trim_matches('\"')).to_string();
    };
        if key == "version".to_string() {
        version = (val.trim_matches('\"')).to_string();
    };
        if key == "output_dir".to_string() {
        output_dir = (val.trim_matches('\"')).to_string();
    }
    };
        if section == "sources".to_string() {
        if key == "files".to_string() {
        if val.starts_with("[".to_string()) {
        let mut rest = val.slice(1, (val.len() as i64));
        let mut closed = false;
        while rest.ends_with("]".to_string()) && (rest.len() as i64) > 0 {
            rest = rest.slice(0, (rest.len() as i64) - 1);
            closed = true;
        }
        for entry in (rest.split(",".to_string()).map(str::to_string).collect::<Vec<_>>()).clone() {
            let mut src = (entry.trim().to_string()).to_string();
            if src.ends_with(",".to_string()) && (src.len() as i64) > 0 {
        src = src.slice(0, (src.len() as i64) - 1);
    };
            src = src.trim().to_string();
            let mut cleaned = "".to_string();
            let mut j = 0;
            while j < (src.len() as i64) {
                let ch = src.chars().nth((j) as usize).unwrap();
                if ch != '\"' {
        cleaned = format!("{}{}", cleaned, (ch).to_string());
    };
                j = j + 1;
            }
            src = cleaned.trim().to_string();
            if !src.is_empty() {
        sources.push((src).to_string())
    }
        }
        if !closed {
        in_sources_array = true;
    }
    }
    }
    };
        if section == "dependencies".to_string() {
        let version_str = val.trim_matches('\"');
        match std::semver::Requirement::parse(&version_str) { Result::Ok(req) => {
        deps.push(Dependency { name: (key).to_string(), version: (version_str).to_string(), requirement: req, registry: Option::None, features: Array::new(), optional: false, dev_only: false, path: Option::None, git: Option::None })
    }, Result::Err(_) => {
        ()
    } }
    }
    }
        }
        if sources.is_empty() {
        sources.push(("src/main.tg".to_string()).to_string())
    };
        Ok(Project { name: (name).to_string(), version: (version).to_string(), dependencies: deps, sources: sources, output_dir: (output_dir).to_string() })
    }, Result::Err(e) => {
        Err(format!("{}{}", format!("{}{}", format!("{}{}", "Cannot read project manifest \'".to_string(), manifest_path), "\': ".to_string()), e))
    } }
    }
    
    pub fn build_project(project: &Project) -> Result<(), String> {
        let opts = default_options();
        let resolved = resolve_project_deps(project)?;
        for dep_src in (resolved.dep_sources).clone() {
            match compile_file(&opts, dep_src) { Result::Ok(_) => {
        ()
    }, Result::Err(e) => {
        return Err(format!("{}{}", "dependency error: ".to_string(), e));
    } }
        }
        let mut cache = load_build_cache(&project.output_dir);
        for src in (project.sources).clone() {
            match std::fs::read_to_string(src.clone()).map_err(|e| e.to_string()) { Result::Ok(content) => {
        if is_stale(&cache, src.clone(), content.clone()) {
        match compile_file(&opts, src.clone()) { Result::Ok(_) => {
        update_cache(&mut cache, src.clone(), content, ("".to_string()).to_string())
    }, Result::Err(e) => {
        return Err(e);
    } }
    } else {
        ()
    }
    }, Result::Err(_) => {
        match compile_file(&opts, src) { Result::Ok(_) => {
        ()
    }, Result::Err(e) => {
        return Err(e);
    } }
    } }
        }
        save_build_cache(&cache);
        Ok(())
    }
    
    #[derive(Clone)]
    struct ResolvedDeps {
        packages: Vec<ResolvedPackage>,
        dep_sources: Vec<String>,
    }
    
    #[derive(Clone)]
    struct ResolvedPackage {
        name: String,
        version: String,
        resolved_path: String,
        checksum: String,
    }
    
    #[derive(Clone)]
    struct DriverLockfile {
        packages: Vec<DriverLockEntry>,
        metadata: Map<String, String>,
        version: i64,
    }
    
    #[derive(Clone)]
    struct DriverLockEntry {
        name: String,
        version: String,
        source: String,
        checksum: String,
        dependencies: Vec<String>,
    }
    
    pub fn resolve_project_deps(project: &Project) -> Result<ResolvedDeps, String> {
        let lockfile = load_lockfile("Tangerine.lock".to_string());
        let mut resolved = ResolvedDeps { packages: Vec::new(), dep_sources: Vec::new() };
        for dep in (project.dependencies).clone() {
            let locked_entry = match lockfile { Option::Some(lf) => {
        find_lock_entry(lf, &dep.name)
    }, Option::None => {
        Option::None
    } };
            let resolved_pkg = resolve_single_dep(&dep, &locked_entry)?;
            let dep_dir = resolved_pkg.resolved_path.clone();
            match discover_sources(&dep_dir) { Result::Ok(srcs) => {
        for s in (srcs).clone() {
            resolved.dep_sources.push(s)
        }
    }, Result::Err(e) => {
        return Err(format!("{}{}", format!("{}{}", format!("{}{}", "Failed to discover sources for \'".to_string(), dep.name.clone()), "\': ".to_string()), e));
    } };
            resolved.packages.push(resolved_pkg)
        }
        write_lockfile("Tangerine.lock".to_string(), &resolved);
        Ok(resolved)
    }
    
    pub fn resolve_single_dep(dep: &Dependency, locked: &Option<DriverLockEntry>) -> Result<ResolvedPackage, String> {
        match dep.path { Option::Some(p) => {
        return Ok(ResolvedPackage { name: dep.name.clone(), version: dep.version.clone(), resolved_path: p.clone(), checksum: hash_directory(p) });
    }, Option::None => {
        ()
    } };
        match dep.git { Option::Some(url) => {
        let clone_dir = format!("{}{}", ".tg_deps/".to_string(), dep.name.clone());
        match locked { Option::Some(entry) => {
        if dir_exists(&clone_dir) && entry.source == url.clone() {
        return Ok(ResolvedPackage { name: dep.name.clone(), version: entry.version.clone(), resolved_path: clone_dir, checksum: entry.checksum.clone() });
    }
    }, Option::None => {
        ()
    } };
        mkdir_p(".tg_deps".to_string());
        let clone_result = run_command("git".to_string(), Vec::from(vec!["clone".to_string(), "--depth".to_string(), "1".to_string(), url.as_str(), clone_dir.as_str()]));
        match clone_result { Result::Ok(_) => {
        Ok(ResolvedPackage { name: dep.name.clone(), version: dep.version.clone(), resolved_path: clone_dir.clone(), checksum: hash_directory(&clone_dir) })
    }, Result::Err(e) => {
        Err(format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "Failed to clone \'".to_string(), dep.name.clone()), "\' from ".to_string()), url.clone()), ": ".to_string()), e))
    } }
    }, Option::None => {
        ()
    } };
        let registry_url = "https://registry.tangerine-lang.org".to_string();
        let pkg_dir = format!("{}{}", format!("{}{}", format!("{}{}", ".tg_deps/".to_string(), dep.name.clone()), "-".to_string()), dep.version.clone());
        if dir_exists(&pkg_dir) {
        match locked { Option::Some(entry) => {
        if entry.version == dep.version {
        return Ok(ResolvedPackage { name: dep.name.clone(), version: entry.version.clone(), resolved_path: pkg_dir, checksum: entry.checksum.clone() });
    }
    }, Option::None => {
        ()
    } }
    };
        mkdir_p(".tg_deps".to_string());
        let fetch_url = format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", registry_url, "/api/v1/packages/".to_string()), dep.name.clone()), "/".to_string()), dep.version.clone()), "/download".to_string());
        let fetch_result = run_command("curl".to_string(), Vec::from(vec!["-sSL".to_string(), "-o".to_string(), format!("{}{}", pkg_dir.clone(), ".tar.gz".to_string()).as_str(), fetch_url.as_str()]));
        match fetch_result { Result::Ok(_) => {
        mkdir_p(&pkg_dir);
        let extract = run_command("tar".to_string(), Vec::from(vec!["xzf".to_string(), format!("{}{}", pkg_dir.clone(), ".tar.gz".to_string()).as_str(), "-C".to_string(), pkg_dir.as_str()]));
        match extract { Result::Ok(_) => {
        Ok(ResolvedPackage { name: dep.name.clone(), version: dep.version.clone(), resolved_path: pkg_dir.clone(), checksum: hash_directory(&pkg_dir) })
    }, Result::Err(e) => {
        Err(format!("{}{}", format!("{}{}", format!("{}{}", "Failed to extract package \'".to_string(), dep.name.clone()), "\': ".to_string()), e))
    } }
    }, Result::Err(e) => {
        Err(format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "Failed to fetch \'".to_string(), dep.name.clone()), "@".to_string()), dep.version.clone()), "\' from registry: ".to_string()), e))
    } }
    }
    
    pub fn discover_sources(dir: &String) -> Result<Vec<String>, String> {
        let manifest = format!("{}{}", dir.clone(), "/Tangerine.toml".to_string());
        match load_project(manifest) { Result::Ok(proj) => {
        let mut sources = Vec::new();
        for s in (proj.sources).clone() {
            sources.push(format!("{}{}", format!("{}{}", dir.clone(), "/".to_string()), s))
        }
        Ok(sources)
    }, Result::Err(_) => {
        let src_dir = format!("{}{}", dir.clone(), "/src".to_string());
        match list_directory(src_dir.clone()) { Result::Ok(files) => {
        let mut sources = Vec::new();
        for f in (files).clone() {
            if f.ends_with(".tg".to_string()) {
        sources.push(format!("{}{}", format!("{}{}", src_dir.clone(), "/".to_string()), f))
    }
        }
        Ok(sources)
    }, Result::Err(_) => {
        match list_directory(dir.clone()) { Result::Ok(files) => {
        let mut sources = Vec::new();
        for f in (files).clone() {
            if f.ends_with(".tg".to_string()) {
        sources.push(format!("{}{}", format!("{}{}", dir.clone(), "/".to_string()), f))
    }
        }
        Ok(sources)
    }, Result::Err(e) => {
        Err(format!("{}{}", "Cannot list directory: ".to_string(), e))
    } }
    } }
    } }
    }
    
    pub fn find_lock_entry(lf: &DriverLockfile, name: &String) -> Option<DriverLockEntry> {
        for entry in (lf.packages).clone() {
            if entry.name == *name {
        return Option::Some(entry.clone());
    }
        }
        Option::None
    }
    
    pub fn load_lockfile(path: &str) -> Option<DriverLockfile> {
        match std::fs::read_to_string((path).to_string()).map_err(|e| e.to_string()) { Result::Ok(content) => {
        parse_lockfile(&content)
    }, Result::Err(_) => {
        Option::None
    } }
    }
    
    pub fn parse_lockfile(content: &String) -> Option<DriverLockfile> {
        let mut packages = Vec::new();
        let mut current_name = ("".to_string()).to_string();
        let mut current_version = ("".to_string()).to_string();
        let mut current_source = ("".to_string()).to_string();
        let mut current_checksum = ("".to_string()).to_string();
        let mut current_deps = Vec::new();
        let mut in_package = false;
        for line in (content.lines().map(str::to_string).collect::<Vec<_>>()).clone() {
            let trimmed = line.trim().to_string();
            if trimmed == "[[package]]".to_string() {
        if in_package && !current_name.is_empty() {
        packages.push(DriverLockEntry { name: current_name.clone(), version: current_version.clone(), source: current_source.clone(), checksum: current_checksum.clone(), dependencies: current_deps.clone() })
    };
        current_name = ("".to_string()).to_string();
        current_version = ("".to_string()).to_string();
        current_source = ("".to_string()).to_string();
        current_checksum = ("".to_string()).to_string();
        current_deps = Vec::new();
        in_package = true;
        continue;
    };
            if !in_package || trimmed.is_empty() || trimmed.starts_with("#".to_string()) {
        continue;
    };
            match trimmed.split_once("=".to_string()) { Option::Some(kv) => {
        let key = kv.0.trim().to_string();
        let val = kv.1.trim().to_string().trim_matches('\"');
        if key == "name".to_string() {
        current_name = (val).to_string();
    };
        if key == "version".to_string() {
        current_version = (val).to_string();
    };
        if key == "source".to_string() {
        current_source = (val).to_string();
    };
        if key == "checksum".to_string() {
        current_checksum = (val).to_string();
    };
        if key == "dependencies".to_string() {
        let arr = val.trim_matches('[').trim_matches(']');
        for dep_name in (arr.split(",".to_string()).map(str::to_string).collect::<Vec<_>>()).clone() {
            let d = dep_name.trim().to_string().trim_matches('\"');
            if !d.is_empty() {
        current_deps.push((d).to_string())
    }
        }
    }
    }, Option::None => {
        ()
    } }
        }
        if in_package && !current_name.is_empty() {
        packages.push(DriverLockEntry { name: current_name.clone(), version: current_version.clone(), source: current_source.clone(), checksum: current_checksum.clone(), dependencies: current_deps.clone() })
    };
        Option::Some(DriverLockfile { packages: packages, metadata: BTreeMap::new(), version: 1 })
    }
    
    pub fn write_lockfile(path: &str, resolved: &ResolvedDeps) -> () {
        let mut out = ("# This file is auto-generated by tg. Do not edit.\n".to_string()).to_string();
        out = format!("{}{}", out, "# Tangerine lockfile v1\n\n".to_string());
        for pkg in (resolved.packages).clone() {
            out = format!("{}{}", out, "[[package]]\n".to_string());
            out = format!("{}{}", format!("{}{}", format!("{}{}", out, "name = \"".to_string()), pkg.name.clone()), "\"\n".to_string());
            out = format!("{}{}", format!("{}{}", format!("{}{}", out, "version = \"".to_string()), pkg.version.clone()), "\"\n".to_string());
            out = format!("{}{}", format!("{}{}", format!("{}{}", out, "source = \"".to_string()), pkg.resolved_path.clone()), "\"\n".to_string());
            out = format!("{}{}", format!("{}{}", format!("{}{}", out, "checksum = \"".to_string()), pkg.checksum.clone()), "\"\n".to_string());
            out = format!("{}{}", out, "dependencies = []\n\n".to_string());
        }
        match std::fs::write((path).to_string(), out).map_err(|e| e.to_string()) { Result::Ok(_) => {
        ()
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "warning: failed to write lockfile: ".to_string(), e))
    } };
    }
    
    pub fn hash_directory(dir: &String) -> String {
        let mut h = 14695981039346656037;
        let prime = 1099511628211;
        match list_directory(dir.clone()) { Result::Ok(files) => {
        let mut sorted = files.clone();
        sorted.sort();
        for f in (sorted).clone() {
            if f.ends_with(".tg".to_string()) {
        match std::fs::read_to_string(format!("{}{}", format!("{}{}", dir.clone(), "/".to_string()), f)).map_err(|e| e.to_string()) { Result::Ok(content) => {
        for c in (content.bytes()).clone() {
            h = h ^ ((c) as u64);
            h = h * prime;
        }
    }, Result::Err(_) => {
        ()
    } }
    }
        }
    }, Result::Err(_) => {
        ()
    } };
        (h).to_string()
    }
    
    #[derive(Clone)]
    struct Workspace {
        root: String,
        members: Vec<String>,
        default_members: Vec<String>,
        shared_output: String,
    }
    
    pub fn load_workspace(path: String) -> Result<Workspace, String> {
        let manifest_path = if path.ends_with("Tangerine.toml".to_string()) {
        path.clone()
    } else {
        format!("{}{}", path.clone(), "/Tangerine.toml".to_string())
    };
        match std::fs::read_to_string(manifest_path.clone()).map_err(|e| e.to_string()) { Result::Ok(content) => {
        let mut members = Vec::new();
        let mut default_members = Vec::new();
        let mut section = "".to_string();
        let mut is_workspace = false;
        for line in (content.lines().map(str::to_string).collect::<Vec<_>>()).clone() {
            let trimmed = line.trim().to_string();
            if trimmed.is_empty() || trimmed.starts_with("#".to_string()) {
        continue;
    };
            if trimmed.starts_with("[".to_string()) && trimmed.ends_with("]".to_string()) {
        section = trimmed.slice(1, (trimmed.len() as i64) - 1);
        if section == "workspace".to_string() {
        is_workspace = true;
    };
        continue;
    };
            if section == "workspace".to_string() {
        match trimmed.split_once("=".to_string()) { Option::Some(kv) => {
        let key = kv.0.trim().to_string();
        let val = kv.1.trim().to_string();
        if key == "members".to_string() {
        let arr = val.trim_matches('[').trim_matches(']');
        for entry in (arr.split(",".to_string()).map(str::to_string).collect::<Vec<_>>()).clone() {
            let m = entry.trim().to_string().trim_matches('\"');
            if !m.is_empty() {
        members.push((m).to_string())
    }
        }
    };
        if key == "default-members".to_string() {
        let arr = val.trim_matches('[').trim_matches(']');
        for entry in (arr.split(",".to_string()).map(str::to_string).collect::<Vec<_>>()).clone() {
            let m = entry.trim().to_string().trim_matches('\"');
            if !m.is_empty() {
        default_members.push((m).to_string())
    }
        }
    }
    }, Option::None => {
        ()
    } }
    }
        }
        if !is_workspace {
        return Err(format!("{}{}", "No [workspace] section in ".to_string(), manifest_path));
    };
        if default_members.is_empty() {
        default_members = members.clone();
    };
        Ok(Workspace { root: path.clone(), members: members, default_members: default_members, shared_output: format!("{}{}", path, "/build".to_string()) })
    }, Result::Err(e) => {
        Err(format!("{}{}", "Cannot read workspace manifest: ".to_string(), e))
    } }
    }
    
    pub fn build_workspace(ws: &Workspace) -> Result<(), String> {
        println!("{}", format!("{}{}", format!("{}{}", "Building workspace with ".to_string(), ((ws.members.len() as i64)).to_string()), " member(s)".to_string()));
        for member in (ws.default_members).clone() {
            let member_path = format!("{}{}", format!("{}{}", ws.root.clone(), "/".to_string()), member.clone());
            println!("{}", format!("{}{}", format!("{}{}", "  Building ".to_string(), member.clone()), "...".to_string()));
            match load_project(member_path.clone()) { Result::Ok(project) => {
        match build_project(&project) { Result::Ok(_) => {
        println!("{}", format!("{}{}", "    \u{2713} ".to_string(), member.clone()))
    }, Result::Err(e) => {
        return Err(format!("{}{}", format!("{}{}", format!("{}{}", "Failed to build workspace member \'".to_string(), member), "\': ".to_string()), e));
    } }
    }, Result::Err(e) => {
        return Err(format!("{}{}", format!("{}{}", format!("{}{}", "Failed to load workspace member \'".to_string(), member), "\': ".to_string()), e));
    } }
        }
        println!("{}", "Workspace build complete.".to_string());
        Ok(())
    }
    
    pub fn cmd_dep(argv: Vec<String>) -> i64 {
        if (argv.len() as i64) < 2 {
        println!("{}", "Usage: tg dep <subcommand>".to_string());
        println!("{}", "".to_string());
        println!("{}", "Subcommands:".to_string());
        println!("{}", "  add <name> [--version <ver>] [--path <path>] [--git <url>]".to_string());
        println!("{}", "  remove <name>".to_string());
        println!("{}", "  list".to_string());
        println!("{}", "  update [<name>]".to_string());
        println!("{}", "  tree".to_string());
        return 1;
    };
        let sub = argv[(1) as usize].clone().clone();
        if sub == "add".to_string() {
        cmd_dep_add(argv)
    } else if sub == "remove".to_string() {
        cmd_dep_remove(argv)
    } else if sub == "list".to_string() {
        cmd_dep_list()
    } else if sub == "update".to_string() {
        cmd_dep_update(argv)
    } else if sub == "tree".to_string() {
        cmd_dep_tree()
    } else {
        eprintln!("{}", format!("{}{}", "Unknown dep subcommand: ".to_string(), sub));
        1
    }
    }
    
    pub fn cmd_dep_add(argv: Vec<String>) -> i64 {
        if (argv.len() as i64) < 3 {
        eprintln!("{}", "Usage: tg dep add <name> [--version <ver>] [--path <path>] [--git <url>]".to_string());
        return 1;
    };
        let name = argv[(2) as usize].clone().clone();
        let mut version = ("*".to_string()).to_string();
        let mut path_opt = Option::None;
        let mut git_opt = Option::None;
        let mut i = 3;
        while i < (argv.len() as i64) {
            if argv[(i) as usize].clone() == "--version".to_string() && i + 1 < (argv.len() as i64) {
        version = argv[(i + 1) as usize].clone().clone();
        i = i + 2;
    } else if argv[(i) as usize].clone() == "--path".to_string() && i + 1 < (argv.len() as i64) {
        path_opt = Option::Some(argv[(i + 1) as usize].clone().clone());
        i = i + 2;
    } else if argv[(i) as usize].clone() == "--git".to_string() && i + 1 < (argv.len() as i64) {
        git_opt = Option::Some(argv[(i + 1) as usize].clone().clone());
        i = i + 2;
    } else {
        i = i + 1;
    }
        }
        match std::fs::read_to_string(("Tangerine.toml".to_string()).to_string()).map_err(|e| e.to_string()) { Result::Ok(content) => {
        let mut new_content = content.clone();
        let dep_line = format!("{}{}", format!("{}{}", name.clone(), " = ".to_string()), match path_opt { Option::Some(p) => {
        format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "{ version = \"".to_string(), version.clone()), "\", path = \"".to_string()), p.clone()), "\" }".to_string())
    }, Option::None => {
        match git_opt { Option::Some(url) => {
        format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "{ version = \"".to_string(), version.clone()), "\", git = \"".to_string()), url.clone()), "\" }".to_string())
    }, Option::None => {
        format!("{}{}", format!("{}{}", "\"".to_string(), version.clone()), "\"".to_string())
    } }
    } });
        if content.contains("[dependencies]".to_string()) {
        new_content = content.replace(&"[dependencies]".to_string(), &format!("{}{}", "[dependencies]\n".to_string(), dep_line).to_string());
    } else {
        new_content = format!("{}{}", format!("{}{}", format!("{}{}", content, "\n[dependencies]\n".to_string()), dep_line), "\n".to_string());
    };
        match std::fs::write(("Tangerine.toml".to_string()).to_string(), new_content).map_err(|e| e.to_string()) { Result::Ok(_) => {
        println!("{}", format!("{}{}", format!("{}{}", format!("{}{}", "Added dependency: ".to_string(), name), " ".to_string()), version));
        0
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Failed to write manifest: ".to_string(), e));
        1
    } }
    }, Result::Err(e) => {
        eprintln!("{}", "No Tangerine.toml found. Run \'tg init\' first.".to_string());
        1
    } }
    }
    
    pub fn cmd_dep_remove(argv: Vec<String>) -> i64 {
        if (argv.len() as i64) < 3 {
        eprintln!("{}", "Usage: tg dep remove <name>".to_string());
        return 1;
    };
        let name = argv[(2) as usize].clone().clone();
        match std::fs::read_to_string(("Tangerine.toml".to_string()).to_string()).map_err(|e| e.to_string()) { Result::Ok(content) => {
        let mut new_lines = Vec::new();
        let mut in_deps = false;
        for line in (content.lines().map(str::to_string).collect::<Vec<_>>()).clone() {
            let trimmed = line.trim().to_string();
            if trimmed == "[dependencies]".to_string() {
        in_deps = true;
        new_lines.push((line).to_string());
        continue;
    };
            if trimmed.starts_with("[".to_string()) && trimmed.ends_with("]".to_string()) {
        in_deps = false;
    };
            if in_deps && trimmed.starts_with(name.as_str()) {
        continue;
    };
            new_lines.push((line).to_string())
        }
        let new_content = new_lines.join("\n".to_string());
        match std::fs::write(("Tangerine.toml".to_string()).to_string(), new_content).map_err(|e| e.to_string()) { Result::Ok(_) => {
        println!("{}", format!("{}{}", "Removed dependency: ".to_string(), name));
        0
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Failed to write manifest: ".to_string(), e));
        1
    } }
    }, Result::Err(_) => {
        eprintln!("{}", "No Tangerine.toml found.".to_string());
        1
    } }
    }
    
