    pub fn cmd_install(argv: Vec<String>) -> i64 {
        if (argv.len() as i64) < 2 {
        println!("{}", "Usage: tg install <package-name> [--version <ver>]".to_string());
        println!("{}", "".to_string());
        println!("{}", "Installs a Tangerine package binary to ~/.tg/bin/".to_string());
        println!("{}", "".to_string());
        println!("{}", "Options:".to_string());
        println!("{}", "  --version <ver>  Install a specific version".to_string());
        println!("{}", "  --global         Install globally (default)".to_string());
        println!("{}", "  --force          Reinstall even if already installed".to_string());
        return 0;
    };
        let pkg_name = argv[(1) as usize].clone().clone();
        let mut version = ("latest".to_string()).to_string();
        let mut force = false;
        let mut i = 2;
        while i < (argv.len() as i64) {
            if argv[(i) as usize].clone() == "--version".to_string() && i + 1 < (argv.len() as i64) {
        version = argv[(i + 1) as usize].clone().clone();
        i = i + 2;
    } else if argv[(i) as usize].clone() == "--force".to_string() {
        force = true;
        i = i + 1;
    } else {
        i = i + 1;
    }
        }
        let install_dir = format!("{}{}", home_dir(), "/.tg/bin".to_string());
        mkdir_p(&install_dir);
        let install_path = format!("{}{}", format!("{}{}", install_dir.clone(), "/".to_string()), pkg_name.clone());
        if !force && file_exists(&install_path) {
        println!("{}", format!("{}{}", format!("{}{}", "Package \'".to_string(), pkg_name.clone()), "\' is already installed. Use --force to reinstall.".to_string()));
        return 0;
    };
        println!("{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "Installing ".to_string(), pkg_name.clone()), " ".to_string()), version.clone()), "...".to_string()));
        let tmp_dir = format!("{}{}", "/tmp/tg_install_".to_string(), pkg_name.clone());
        mkdir_p(&tmp_dir);
        let registry_url = "https://registry.tangerine-lang.org".to_string();
        let fetch_url = format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", registry_url, "/api/v1/packages/".to_string()), pkg_name.clone()), "/".to_string()), version.clone()), "/download".to_string());
        let fetch_result = run_command("curl".to_string(), Vec::from(vec!["-sSL".to_string(), "-o".to_string(), format!("{}{}", tmp_dir.clone(), "/pkg.tar.gz".to_string()).as_str(), fetch_url.as_str()]));
        match fetch_result { Result::Ok(_) => {
        let extract = run_command("tar".to_string(), Vec::from(vec!["xzf".to_string(), format!("{}{}", tmp_dir.clone(), "/pkg.tar.gz".to_string()).as_str(), "-C".to_string(), tmp_dir.as_str()]));
        match extract { Result::Ok(_) => {
        match load_project(tmp_dir.clone()) { Result::Ok(project) => {
        match build_project(&project) { Result::Ok(_) => {
        let binary = format!("{}{}", format!("{}{}", tmp_dir.clone(), "/build/".to_string()), pkg_name.clone());
        let cp_result = run_command("cp".to_string(), Vec::from(vec![binary.as_str(), install_path.as_str()]));
        match cp_result { Result::Ok(_) => {
        let _ = run_command("chmod".to_string(), Vec::from(vec!["+x".to_string(), install_path.as_str()]));
        println!("{}", format!("{}{}", format!("{}{}", format!("{}{}", "Installed ".to_string(), pkg_name.clone()), " to ".to_string()), install_path));
        0
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Failed to copy binary: ".to_string(), e));
        1
    } }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Build failed: ".to_string(), e));
        1
    } }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Invalid package: ".to_string(), e));
        1
    } }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Failed to extract package: ".to_string(), e));
        1
    } }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Failed to download package: ".to_string(), e));
        1
    } }
    }
    
    pub fn cmd_self_update(argv: Vec<String>) -> i64 {
        println!("{}", "Tangerine self-update".to_string());
        println!("{}", "".to_string());
        let current_version = VERSION;
        let os = detect_os();
        let arch = detect_arch();
        let target = format!("{}{}", format!("{}{}", arch, "-".to_string()), os);
        println!("{}", format!("{}{}", "Current version: ".to_string(), current_version));
        println!("{}", format!("{}{}", "Target: ".to_string(), target.clone()));
        let release_url = "https://releases.tangerine-lang.org/latest/version".to_string();
        println!("{}", "Checking for updates...".to_string());
        let version_result = run_command("curl".to_string(), Vec::from(vec!["-sSL".to_string(), release_url.as_str()]));
        match version_result { Result::Ok(latest_version) => {
        let latest = (latest_version.trim().to_string()).to_string();
        if latest == current_version {
        println!("{}", format!("{}{}", format!("{}{}", "Already up to date (v".to_string(), current_version), ").".to_string()));
        return 0;
    };
        println!("{}", format!("{}{}", "New version available: v".to_string(), latest.clone()));
        println!("{}", "Downloading...".to_string());
        let download_url = format!("{}{}", format!("{}{}", format!("{}{}", format!("{}{}", "https://releases.tangerine-lang.org/".to_string(), latest.clone()), "/tg-".to_string()), target), ".tar.gz".to_string());
        let tmp = "/tmp/tg_self_update.tar.gz".to_string();
        let dl = run_command("curl".to_string(), Vec::from(vec!["-sSL".to_string(), "-o".to_string(), tmp, download_url.as_str()]));
        match dl { Result::Ok(_) => {
        let tmp_dir = "/tmp/tg_self_update".to_string();
        mkdir_p(tmp_dir);
        let extract = run_command("tar".to_string(), Vec::from(vec!["xzf".to_string(), tmp, "-C".to_string(), tmp_dir]));
        match extract { Result::Ok(_) => {
        let current_binary = argv[(0) as usize].clone().clone();
        let new_binary = format!("{}{}", (tmp_dir).to_string(), "/tg".to_string());
        let cp = run_command("cp".to_string(), Vec::from(vec![new_binary.as_str(), current_binary.as_str()]));
        match cp { Result::Ok(_) => {
        let _ = run_command("chmod".to_string(), Vec::from(vec!["+x".to_string(), current_binary.as_str()]));
        println!("{}", format!("{}{}", format!("{}{}", "Updated to v".to_string(), latest), " successfully!".to_string()));
        0
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Failed to replace binary: ".to_string(), e));
        eprintln!("{}", "Try running with sudo.".to_string());
        1
    } }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Failed to extract update: ".to_string(), e));
        1
    } }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Failed to download update: ".to_string(), e));
        1
    } }
    }, Result::Err(e) => {
        eprintln!("{}", format!("{}{}", "Failed to check for updates: ".to_string(), e));
        1
    } }
    }
    
    pub fn detect_os() -> String {
        match run_command("uname".to_string(), Vec::from(vec!["-s".to_string()])) { Result::Ok(out) => {
        let os = out.trim().to_string().to_lowercase();
        if os.contains("darwin".to_string()) {
        ("apple-darwin".to_string()).to_string()
    } else if os.contains("linux".to_string()) {
        ("unknown-linux-gnu".to_string()).to_string()
    } else {
        ("unknown".to_string()).to_string()
    }
    }, Result::Err(_) => {
        ("unknown".to_string()).to_string()
    } }
    }
    
    pub fn detect_arch() -> String {
        match run_command("uname".to_string(), Vec::from(vec!["-m".to_string()])) { Result::Ok(out) => {
        let arch = out.trim().to_string().to_lowercase();
        if arch == "x86_64".to_string() || arch == "amd64".to_string() {
        ("x86_64".to_string()).to_string()
    } else if arch == "arm64".to_string() || arch == "aarch64".to_string() {
        ("aarch64".to_string()).to_string()
    } else {
        (arch).to_string()
    }
    }, Result::Err(_) => {
        ("unknown".to_string()).to_string()
    } }
    }
    
