    pub fn compile(source: String) -> Result<String, String> {
        let tokens = tokenize(source);
        let (ast, parse_diags) = parse(tokens);
        if diag_has_errors(&parse_diags) {
        return Err(format!("{}{}", "Parse error: ".to_string(), parse_diags.diagnostics[(0) as usize].clone().message));
    };
        let type_errors = type_check(&ast);
        if !type_errors.is_empty() {
        return Err(format!("{}{}", "Type error: ".to_string(), type_errors[(0) as usize].clone().message));
    };
        let borrow_errors = borrow_check(&ast);
        if !borrow_errors.is_empty() {
        return Err(format!("{}{}", "Borrow error: ".to_string(), borrow_errors[(0) as usize].clone().message));
    };
        let mut mir = lower_to_mir(&ast);
        let mut mono_cache = mono_cache_new();
        monomorphize_program(&mut mir, &mut mono_cache);
        optimize_mir(&mut mir, 1);
        let target = detect_host_target();
        let obj_bytes = generate_object_file(&mir, target);
        Ok(format!("{}{}", format!("{}{}", "Native object generated (".to_string(), ((obj_bytes.len() as i64)).to_string()), " bytes)".to_string()))
    }
    
    pub fn check(source: String) -> Vec<String> {
        let mut errors = Vec::new();
        let tokens = tokenize(source);
        let (ast, parse_diags) = parse(tokens);
        if diag_has_errors(&parse_diags) {
        for e in (parse_diags.diagnostics).clone() {
            errors.push(format!("{}{}", "Parse error: ".to_string(), e.message))
        }
        errors
    } else {
        for e in (type_check(&ast)).clone() {
            errors.push(format!("{}{}", "Type error: ".to_string(), e.message))
        }
        for e in (borrow_check(&ast)).clone() {
            errors.push(format!("{}{}", "Borrow error: ".to_string(), e.message))
        }
        errors
    }
    }
    
    pub fn parse_only(source: String) -> Result<Program, String> {
        let tokens = tokenize(source);
        let (ast, parse_diags) = parse(tokens);
        match diag_has_errors(&parse_diags) { true => {
        Err(parse_diags.diagnostics[(0) as usize].clone().message.clone())
    }, false => {
        Ok(ast)
    } }
    }
    
    pub fn tokenize_only(source: String) -> Vec<Token> {
        tokenize(source)
    }
    
    pub fn format(source: String) -> Result<String, String> {
        let mut output = "".to_string();
        let mut indent_level = 0;
        let mut prev_was_blank = false;
        for line in (source.lines().map(str::to_string).collect::<Vec<_>>()).clone() {
            let trimmed = line.trim().to_string();
            if trimmed.is_empty() {
        if !prev_was_blank {
        output = format!("{}{}", output, "\n".to_string());
        prev_was_blank = true;
    };
        continue;
    };
            prev_was_blank = false;
            if trimmed.starts_with("end".to_string()) || trimmed.starts_with("elsif".to_string()) || trimmed.starts_with("else".to_string()) || trimmed.starts_with("when".to_string()) {
        if indent_level > 0 {
        indent_level = indent_level - 1;
    }
    };
            let mut indent_str = "".to_string();
            let mut i = 0;
            while i < indent_level {
                indent_str = format!("{}{}", indent_str, "  ".to_string());
                i = i + 1;
            }
            output = format!("{}{}", output + indent_str + trimmed, "\n".to_string());
            if trimmed.starts_with("def ".to_string()) || trimmed.starts_with("pub def ".to_string()) || trimmed.starts_with("struct ".to_string()) || trimmed.starts_with("pub struct ".to_string()) || trimmed.starts_with("enum ".to_string()) || trimmed.starts_with("pub enum ".to_string()) || trimmed.starts_with("trait ".to_string()) || trimmed.starts_with("impl ".to_string()) || trimmed.starts_with("module ".to_string()) || trimmed.starts_with("if ".to_string()) || trimmed.starts_with("elsif ".to_string()) || trimmed == "else".to_string() || trimmed.starts_with("match ".to_string()) || trimmed.starts_with("when ".to_string()) || trimmed.starts_with("for ".to_string()) || trimmed.starts_with("while ".to_string()) || trimmed.starts_with("loop".to_string()) {
        indent_level = indent_level + 1;
    };
            if trimmed.starts_with("when ".to_string()) && trimmed.contains(" then ".to_string()) && !trimmed.ends_with("then".to_string()) {
        indent_level = indent_level - 1;
    }
        }
        Ok(output)
    }
    
