    pub fn write32_at(data: &mut Vec<u8>, offset: i64, value: u32) -> () {
        data[(offset) as usize] = ((value & 0xFF) as u8);
        data[(offset + 1) as usize] = ((value >> 8 & 0xFF) as u8);
        data[(offset + 2) as usize] = ((value >> 16 & 0xFF) as u8);
        data[(offset + 3) as usize] = ((value >> 24 & 0xFF) as u8);
    }
    
    pub fn write64_at(data: &mut Vec<u8>, offset: i64, value: u64) -> () {
        let mut i = 0;
        while i < 8 {
            data[(offset + i) as usize] = ((value >> i * 8 & 0xFF) as u8);
            i = i + 1;
        }
    }
    
    pub fn align_up_u64(value: u64, alignment: u64) -> u64 {
        value + alignment - ((1) as u64) / alignment * alignment
    }
    
    pub fn add_u64(left: u64, right: u64) -> u64 {
        left + right
    }
    
