        ((data[(offset) as usize].clone()) as u32) | ((data[(offset + 1) as usize].clone()) as u32) << 8 | ((data[(offset + 2) as usize].clone()) as u32) << 16 | ((data[(offset + 3) as usize].clone()) as u32) << 24
