    pub fn count_name_occurrences(source: &String, name: &String) -> i64 {
        let mut count = 0;
        let mut pos = 0;
        let name_len = (name.len() as i64);
        while pos + name_len <= (source.len() as i64) {
            if source.slice(pos, pos + name_len) == name.clone() {
        let before_ok = pos == 0 || !is_ident_char(source.chars().nth((pos - 1) as usize).unwrap());
        let after_ok = pos + name_len >= (source.len() as i64) || !is_ident_char(source.chars().nth((pos + name_len) as usize).unwrap());
        if before_ok && after_ok {
        count = count + 1;
    };
        pos = pos + name_len;
    } else {
        pos = pos + 1;
    }
        }
        count
    }
    
    pub fn is_ident_char(c: char) -> bool {
        c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_'
    }
    
    #[derive(Clone, Copy)]
    enum LintLevel {
        Error,
        Warning,
        Info,
    }
    
    #[derive(Clone)]
    struct LintDiagnostic {
        lint_name: String,
        level: LintLevel,
        message: String,
        file: String,
        line: u64,
        column: u64,
        span: Option<Span>,
        suggestion: Option<String>,
    }
    
    #[derive(Clone)]
    struct LintConfig {
        denied: Vec<String>,
        warned: Vec<String>,
        allowed: Vec<String>,
        json_output: bool,
    }
    
    pub fn default_lint_config() -> LintConfig {
        LintConfig { denied: Vec::new(), warned: Vec::new(), allowed: Vec::new(), json_output: false }
    }
    
    pub fn duplicate_lint_config(config: &LintConfig) -> LintConfig {
        LintConfig { denied: config.denied.clone(), warned: config.warned.clone(), allowed: config.allowed.clone(), json_output: config.json_output }
    }
    
    trait LintPass {
        fn name(&self) -> String;
        fn description(&self) -> String;
        fn default_level(&self) -> LintLevel;
        fn check_item(&self, ctx: &mut LintContext, item: &Item) -> ();
        fn check_expr(&self, ctx: &mut LintContext, expr: &Expr) -> ();
        fn check_stmt(&self, ctx: &mut LintContext, stmt: &Stmt) -> ();
        fn check_function(&self, ctx: &mut LintContext, func: &FunctionDecl) -> ();
    }
    
    #[derive(Clone)]
    struct LintContext {
        file: String,
        source: String,
        diagnostics: Vec<LintDiagnostic>,
        config: LintConfig,
        suppressed: Set<String>,
    }
    
    pub fn lint_context_new(file: String, source: String, config: LintConfig) -> LintContext {
        LintContext { file: file, source: source, diagnostics: Vec::new(), config: config, suppressed: Set::new() }
    }
    
    impl LintContext {
        fn emit(&mut self, lint_name: String, level: LintLevel, message: String, span: Span) -> () {
            if self.suppressed.contains(lint_name.clone()) {
        return;
    };
            if self.config.allowed.contains(lint_name.clone()) {
        return;
    };
            let effective_level = if self.config.denied.contains(lint_name.clone()) {
        LintLevel::Error
    } else if self.config.warned.contains(lint_name.clone()) {
        LintLevel::Warning
    } else {
        level
    };
            let (line, col) = offset_to_line_col(&self.source, span.start);
            self.diagnostics.push(LintDiagnostic { lint_name: lint_name, level: effective_level, message: message, file: self.file.clone(), line: line, column: col, span: Option::Some(span), suggestion: Option::None });
        }
        fn emit_with_suggestion(&mut self, lint_name: String, level: LintLevel, message: String, span: Span, suggestion: String) -> () {
            if self.suppressed.contains(lint_name.clone()) {
        return;
    };
            if self.config.allowed.contains(lint_name.clone()) {
        return;
    };
            let effective_level = if self.config.denied.contains(lint_name.clone()) {
        LintLevel::Error
    } else if self.config.warned.contains(lint_name.clone()) {
        LintLevel::Warning
    } else {
        level
    };
            let (line, col) = offset_to_line_col(&self.source, span.start);
            self.diagnostics.push(LintDiagnostic { lint_name: lint_name, level: effective_level, message: message, file: self.file.clone(), line: line, column: col, span: Option::Some(span), suggestion: Option::Some(suggestion) });
        }
        fn push_allow(&mut self, lint_name: String) -> () {
            self.suppressed.insert(lint_name);
        }
        fn pop_allow(&mut self, lint_name: String) -> () {
            self.suppressed.remove(&lint_name);
        }
    }
    
    pub fn offset_to_line_col(source: &String, offset: u64) -> (u64, u64) {
        let mut line = 1;
        let mut col = 1;
        let mut i = 0;
        while i < offset && i < (source.len() as i64) {
            if source.chars().nth((i) as usize).unwrap() == '\n' {
        line = line + 1;
        col = 1;
    } else {
        col = col + 1;
    };
            i = i + 1;
        }
        (line, col)
    }
    
    #[derive(Clone)]
    struct UnusedVariablesLint {
    }
    
    impl LintPass for UnusedVariablesLint {
        fn name(&self) -> String {
            ("unused_variables".to_string()).to_string()
        }
        fn description(&self) -> String {
            ("Detects variables that are declared but never used".to_string()).to_string()
        }
        fn default_level(&self) -> LintLevel {
            LintLevel::Warning
        }
        fn check_item(&self, ctx: &mut LintContext, item: &Item) -> () {
            ();
        }
        fn check_expr(&self, ctx: &mut LintContext, expr: &Expr) -> () {
            ();
        }
        fn check_stmt(&self, ctx: &mut LintContext, stmt: &Stmt) -> () {
            ();
        }
        fn check_function(&self, ctx: &mut LintContext, func: &FunctionDecl) -> () {
            let mut declared = BTreeMap::new();
            match func.body { FnBody::FnBlock(block) => {
        collect_declarations(&block, &mut declared);
        mark_used_in_block(&block, &mut declared);
        for entry in (declared).clone() {
            if !entry.value.1 && !entry.key.starts_with("_".to_string()) {
        ctx.emit_with_suggestion(("unused_variables".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "unused variable `".to_string(), entry.key), "`".to_string()), entry.value.0, format!("{}{}", "prefix with underscore: _".to_string(), entry.key))
    }
        }
    }, _ => {
        ()
    } };
        }
    }
    
    pub fn collect_declarations(block: &Block, declared: &mut Map<String, (Span, bool)>) -> () {
        for stmt in (block.stmts).clone() {
            match stmt.kind { StmtKind::StmtLet(pattern, _, _, _) => {
        collect_pattern_names(&pattern, declared, stmt.span)
    }, _ => {
        ()
    } }
        }
    }
    
    pub fn collect_pattern_names(pattern: &Pattern, declared: &mut Map<String, (Span, bool)>, span: Span) -> () {
        match pattern.kind { PatternKind::Ident(name, _) => {
        declared.insert(name.clone(), (span, false))
    }, PatternKind::Tuple(pats) => {
        for p in (pats).clone() {
            collect_pattern_names(&p, declared, span)
        }
    }, PatternKind::Struct(_, fields) => {
        for (_, p) in (fields).clone() {
            collect_pattern_names(&p, declared, span)
        }
    }, PatternKind::Variant(_, pats) => {
        for p in (pats).clone() {
            collect_pattern_names(&p, declared, span)
        }
    }, PatternKind::Array(pats) => {
        for p in (pats).clone() {
            collect_pattern_names(&p, declared, span)
        }
    }, PatternKind::Or(pats) => {
        for p in (pats).clone() {
            collect_pattern_names(&p, declared, span)
        }
    }, PatternKind::Ref(inner) => {
        collect_pattern_names(&inner, declared, span)
    }, PatternKind::RefMut(inner) => {
        collect_pattern_names(&inner, declared, span)
    }, _ => {
        ()
    } };
    }
    
    pub fn mark_used_in_block(block: &Block, declared: &mut Map<String, (Span, bool)>) -> () {
        for stmt in (block.stmts).clone() {
            mark_used_in_stmt(stmt, declared)
        }
    }
    
    pub fn mark_used_in_stmt(stmt: &Stmt, declared: &mut Map<String, (Span, bool)>) -> () {
        match stmt.kind { StmtKind::StmtExpr(expr) => {
        mark_used_in_expr(expr, declared)
    }, StmtKind::StmtLet(_, _, init, _) => {
        mark_used_in_expr(init, declared)
    }, StmtKind::StmtFor(_, iter, body) => {
        mark_used_in_expr(iter, declared);
        mark_used_in_block(body, declared)
    }, StmtKind::StmtWhile(cond, body) => {
        mark_used_in_expr(cond, declared);
        mark_used_in_block(body, declared)
    }, StmtKind::StmtLoop(body) => {
        mark_used_in_block(body, declared)
    }, StmtKind::StmtReturn(val) => {
        match val { Option::Some(v) => {
        mark_used_in_expr(v, declared)
    }, Option::None => {
        ()
    } }
    }, _ => {
        ()
    } };
    }
    
    pub fn mark_used_in_expr(expr: &Expr, declared: &mut Map<String, (Span, bool)>) -> () {
        match expr.kind { ExprKind::ExprIdent(name) => {
        match declared.get_mut(name) { Option::Some(entry) => {
        entry.1 = true;
    }, Option::None => {
        ()
    } }
    }, ExprKind::ExprBinaryOp(_, left, right) => {
        mark_used_in_expr(left, declared);
        mark_used_in_expr(right, declared)
    }, ExprKind::ExprUnaryOp(_, operand) => {
        mark_used_in_expr(operand, declared)
    }, ExprKind::ExprCall(callee, args) => {
        mark_used_in_expr(callee, declared);
        for arg in (args).clone() {
            mark_used_in_expr(arg, declared)
        }
    }, ExprKind::ExprMethodCall(receiver, _, _, args) => {
        mark_used_in_expr(receiver, declared);
        for arg in (args).clone() {
            mark_used_in_expr(arg, declared)
        }
    }, ExprKind::ExprFieldAccess(obj, _) => {
        mark_used_in_expr(obj, declared)
    }, ExprKind::ExprIndex(arr, idx) => {
        mark_used_in_expr(arr, declared);
        mark_used_in_expr(idx, declared)
    }, ExprKind::ExprIf(if_stmt) => {
        mark_used_in_expr(&if_stmt.cond, declared);
        mark_used_in_block(&if_stmt.then_block, declared);
        for elsif_branch in (if_stmt.elsif_branches).clone() {
            let (econd, ebody) = elsif_branch;
            mark_used_in_expr(&econd, declared);
            mark_used_in_block(&ebody, declared)
        }
        match &if_stmt.else_block { Option::Some(e) => {
        mark_used_in_block(e, declared)
    }, Option::None => {
        ()
    } }
    }, ExprKind::ExprMatch(m) => {
        mark_used_in_expr(&m.scrutinee, declared);
        for arm in (m.arms).clone() {
            mark_used_in_block(&arm.body, declared)
        }
    }, ExprKind::ExprBlock(block) => {
        for s in (block.stmts).clone() {
            mark_used_in_stmt(s, declared)
        }
    }, ExprKind::ExprClosure(params, _ret_ty, body) => {
        mark_used_in_expr(body, declared)
    }, ExprKind::ExprAssign(target, value) => {
        mark_used_in_expr(target, declared);
        mark_used_in_expr(value, declared)
    }, _ => {
        ()
    } };
    }
    
    #[derive(Clone)]
    struct UnusedImportsLint {
    }
    
    impl LintPass for UnusedImportsLint {
        fn name(&self) -> String {
            ("unused_imports".to_string()).to_string()
        }
        fn description(&self) -> String {
            ("Detects imported names that are not used in the file".to_string()).to_string()
        }
        fn default_level(&self) -> LintLevel {
            LintLevel::Warning
        }
        fn check_item(&self, ctx: &mut LintContext, item: &Item) -> () {
            match item.kind { ItemKind::Use(u) => {
        match u.names { Option::Some(names) => {
        for imported_name in (names).clone() {
            let count = count_name_occurrences(&ctx.source, &imported_name);
            if count <= 1 {
        ctx.emit(("unused_imports".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "unused import: `".to_string(), imported_name), "`".to_string()), item.span)
    }
        }
    }, Option::None => {
        ()
    } }
    }, _ => {
        ()
    } };
        }
        fn check_expr(&self, ctx: &mut LintContext, expr: &Expr) -> () {
            ();
        }
        fn check_stmt(&self, ctx: &mut LintContext, stmt: &Stmt) -> () {
            ();
        }
        fn check_function(&self, ctx: &mut LintContext, func: &FunctionDecl) -> () {
            ();
        }
    }
    
    #[derive(Clone)]
    struct DeadCodeLint {
    }
    
    impl LintPass for DeadCodeLint {
        fn name(&self) -> String {
            ("dead_code".to_string()).to_string()
        }
        fn description(&self) -> String {
            ("Detects functions and types that are never referenced".to_string()).to_string()
        }
        fn default_level(&self) -> LintLevel {
            LintLevel::Warning
        }
        fn check_item(&self, ctx: &mut LintContext, item: &Item) -> () {
            match item.kind { ItemKind::Function(func) => {
        if func.vis != Visibility::Public && func.name != "main".to_string() {
        let count = count_occurrences(&ctx.source, func.name.clone());
        if count <= 1 {
        ctx.emit(("dead_code".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "function `".to_string(), func.name), "` is never used".to_string()), item.span)
    }
    }
    }, ItemKind::Struct(s) => {
        if s.vis != Visibility::Public {
        let count = count_occurrences(&ctx.source, s.name.clone());
        if count <= 1 {
        ctx.emit(("dead_code".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "struct `".to_string(), s.name), "` is never used".to_string()), item.span)
    }
    }
    }, _ => {
        ()
    } };
        }
        fn check_expr(&self, ctx: &mut LintContext, expr: &Expr) -> () {
            ();
        }
        fn check_stmt(&self, ctx: &mut LintContext, stmt: &Stmt) -> () {
            ();
        }
        fn check_function(&self, ctx: &mut LintContext, func: &FunctionDecl) -> () {
            ();
        }
    }
    
    #[derive(Clone)]
    struct NeedlessMutLint {
    }
    
    impl LintPass for NeedlessMutLint {
        fn name(&self) -> String {
            ("needless_mut".to_string()).to_string()
        }
        fn description(&self) -> String {
            ("Detects `mut` variables that are never mutated".to_string()).to_string()
        }
        fn default_level(&self) -> LintLevel {
            LintLevel::Warning
        }
        fn check_item(&self, ctx: &mut LintContext, item: &Item) -> () {
            ();
        }
        fn check_expr(&self, ctx: &mut LintContext, expr: &Expr) -> () {
            ();
        }
        fn check_stmt(&self, ctx: &mut LintContext, stmt: &Stmt) -> () {
            ();
        }
        fn check_function(&self, ctx: &mut LintContext, func: &FunctionDecl) -> () {
            match func.body { FnBody::FnBlock(block) => {
        let mut mut_vars = BTreeMap::new();
        for stmt in (block.stmts).clone() {
            match stmt.kind { StmtKind::StmtLet(pattern, _, _, is_mut) => {
        if is_mut {
        match pattern { Pattern::Ident(name) => {
        mut_vars.insert(name.clone(), stmt.span)
    }, _ => {
        ()
    } }
    }
    }, _ => {
        ()
    } }
        }
        let assigned = find_assignments_in_block(&block);
        for entry in (mut_vars).clone() {
            if !assigned.contains(entry.key.clone()) {
        ctx.emit_with_suggestion(("needless_mut".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "variable `".to_string(), entry.key), "` is declared `mut` but never mutated".to_string()), entry.value, format!("{}{}", "remove `mut`: let ".to_string(), entry.key))
    }
        }
    }, _ => {
        ()
    } };
        }
    }
    
    pub fn find_assignments_in_block(block: &Block) -> Set<String> {
        let mut assigned = Set::new();
        for stmt in (block.stmts).clone() {
            find_assignments_in_stmt(stmt, &mut assigned)
        }
        assigned
    }
    
    pub fn find_assignments_in_stmt(stmt: &Stmt, assigned: &mut Set<String>) -> () {
        match stmt.kind { StmtKind::StmtExpr(expr) => {
        find_assignments_in_expr(expr, assigned)
    }, StmtKind::StmtFor(_, iter, body) => {
        find_assignments_in_expr(iter, assigned);
        for s in (body.stmts).clone() {
            find_assignments_in_stmt(s, assigned)
        }
    }, StmtKind::StmtWhile(cond, body) => {
        find_assignments_in_expr(cond, assigned);
        for s in (body.stmts).clone() {
            find_assignments_in_stmt(s, assigned)
        }
    }, StmtKind::StmtLoop(body) => {
        for s in (body.stmts).clone() {
            find_assignments_in_stmt(s, assigned)
        }
    }, _ => {
        ()
    } };
    }
    
    pub fn find_assignments_in_expr(expr: &Expr, assigned: &mut Set<String>) -> () {
        match expr.kind { ExprKind::ExprAssign(target, value) => {
        match target.kind { ExprKind::ExprIdent(name) => {
        assigned.insert(name.clone())
    }, _ => {
        ()
    } };
        find_assignments_in_expr(value, assigned)
    }, ExprKind::ExprMethodCall(receiver, method, _, _) => {
        match receiver.kind { ExprKind::ExprIdent(name) => {
        assigned.insert(name.clone())
    }, _ => {
        ()
    } }
    }, ExprKind::ExprBinaryOp(_, left, right) => {
        find_assignments_in_expr(left, assigned);
        find_assignments_in_expr(right, assigned)
    }, ExprKind::ExprCall(callee, args) => {
        find_assignments_in_expr(callee, assigned);
        for arg in (args).clone() {
            find_assignments_in_expr(arg, assigned)
        }
    }, ExprKind::ExprIf(if_stmt) => {
        find_assignments_in_expr(&if_stmt.cond, assigned);
        for s in (if_stmt.then_block.stmts).clone() {
            find_assignments_in_stmt(s, assigned)
        }
        match if_stmt.else_block { Option::Some(e) => {
        for s in (e.stmts).clone() {
            find_assignments_in_stmt(s, assigned)
        }
    }, Option::None => {
        ()
    } }
    }, ExprKind::ExprMatch(m) => {
        find_assignments_in_expr(&m.scrutinee, assigned);
        for arm in (m.arms).clone() {
            for s in (arm.body.stmts).clone() {
                find_assignments_in_stmt(s, assigned)
            }
        }
    }, ExprKind::ExprBlock(block) => {
        for s in (block.stmts).clone() {
            find_assignments_in_stmt(s, assigned)
        }
    }, ExprKind::ExprUnaryOp(_, inner) => {
        find_assignments_in_expr(inner, assigned)
    }, ExprKind::ExprCast(inner, _) => {
        find_assignments_in_expr(inner, assigned)
    }, ExprKind::ExprDeref(inner) => {
        find_assignments_in_expr(inner, assigned)
    }, ExprKind::ExprFieldAccess(recv, _) => {
        find_assignments_in_expr(recv, assigned)
    }, ExprKind::ExprIndex(recv, idx) => {
        find_assignments_in_expr(recv, assigned);
        find_assignments_in_expr(idx, assigned)
    }, ExprKind::ExprRef(inner) => {
        find_assignments_in_expr(inner, assigned)
    }, ExprKind::ExprRefMut(inner) => {
        find_assignments_in_expr(inner, assigned)
    }, ExprKind::ExprTupleLit(elems) => {
        for e in (elems).clone() {
            find_assignments_in_expr(e, assigned)
        }
    }, ExprKind::ExprArrayLit(elems) => {
        for e in (elems).clone() {
            find_assignments_in_expr(e, assigned)
        }
    }, _ => {
        ()
    } };
    }
    
    #[derive(Clone)]
    struct NamingConventionsLint {
    }
    
    impl LintPass for NamingConventionsLint {
        fn name(&self) -> String {
            ("naming_conventions".to_string()).to_string()
        }
        fn description(&self) -> String {
            ("Enforces Tangerine naming conventions".to_string()).to_string()
        }
        fn default_level(&self) -> LintLevel {
            LintLevel::Warning
        }
        fn check_item(&self, ctx: &mut LintContext, item: &Item) -> () {
            match item.kind { ItemKind::Function(func) => {
        if !is_snake_case(func.name.clone()) && !func.name.starts_with("_".to_string()) {
        ctx.emit_with_suggestion(("naming_conventions".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "function `".to_string(), func.name), "` should be snake_case".to_string()), item.span, format!("{}{}", "rename to: ".to_string(), to_snake_case(func.name.clone())))
    }
    }, ItemKind::Struct(s) => {
        if !is_pascal_case(s.name.clone()) {
        ctx.emit(("naming_conventions".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "struct `".to_string(), s.name), "` should be PascalCase".to_string()), item.span)
    }
    }, ItemKind::Enum(e) => {
        if !is_pascal_case(e.name.clone()) {
        ctx.emit(("naming_conventions".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "enum `".to_string(), e.name), "` should be PascalCase".to_string()), item.span)
    }
    }, ItemKind::Trait(t) => {
        if !is_pascal_case(t.name.clone()) {
        ctx.emit(("naming_conventions".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "trait `".to_string(), t.name), "` should be PascalCase".to_string()), item.span)
    }
    }, ItemKind::Const(c) => {
        if !is_screaming_snake_case(c.name.clone()) && !is_snake_case(c.name.clone()) {
        ctx.emit(("naming_conventions".to_string()).to_string(), LintLevel::Warning, format!("{}{}", format!("{}{}", "constant `".to_string(), c.name), "` should be SCREAMING_SNAKE_CASE or snake_case".to_string()), item.span)
    }
    }, _ => {
        ()
    } };
        }
        fn check_expr(&self, ctx: &mut LintContext, expr: &Expr) -> () {
            ();
        }
        fn check_stmt(&self, ctx: &mut LintContext, stmt: &Stmt) -> () {
            ();
        }
        fn check_function(&self, ctx: &mut LintContext, func: &FunctionDecl) -> () {
            ();
        }
    }
    
