    pub fn extract_local_from_operand(op: &MirOperand) -> Option<LocalId> {
        match op.kind { MirOperandKind::MirCopy(place) => {
        if place.projections.is_empty() {
        Option::Some(place.local.clone())
    } else {
        Option::None
    }
    }, MirOperandKind::MirMovePlace(place) => {
        if place.projections.is_empty() {
        Option::Some(place.local.clone())
    } else {
        Option::None
    }
    }, _ => {
        Option::None
    } }
    }
    
