        let start = match ranges.get(&place.local.id) { Option::Some(range) => {
        match range.min { Option::Some(min_val) => {
        min_val
    }, Option::None => {
        0
    } }
    }, Option::None => {
        0
    } };
        if step > 0 {
        let _ = ranges.insert(place.local.id, ValueRange { min: Option::Some(start), max: Option::None });
    }
