    #[derive(Clone, Copy)]
    enum Mode {
        Dev,
        Strict,
        Production,
        Hardened,
    }
    
    #[derive(Clone)]
    struct ModeConfig {
        mode: Mode,
        auto_escalate: bool,
        allow_stubs: bool,
        enforce_contracts: bool,
        enforce_effects: bool,
        enforce_budgets: bool,
        enforce_capabilities: bool,
        enforce_coverage: bool,
        gate_on_score: bool,
        require_docs_for_pub: bool,
        require_tests_for_pub: bool,
        forbid_unsafe_no_reason: bool,
        forbid_all_unsafe: bool,
        require_code_review: bool,
        enforce_memory_safety: bool,
        audit_dependencies: bool,
    }
    
    pub fn dev_config() -> ModeConfig {
        ModeConfig { mode: Mode::Dev, auto_escalate: true, allow_stubs: true, enforce_contracts: false, enforce_effects: false, enforce_budgets: false, enforce_capabilities: true, enforce_coverage: false, gate_on_score: false, require_docs_for_pub: false, require_tests_for_pub: false, forbid_unsafe_no_reason: true, forbid_all_unsafe: false, require_code_review: false, enforce_memory_safety: false, audit_dependencies: false }
    }
    
    pub fn strict_config() -> ModeConfig {
        ModeConfig { mode: Mode::Strict, auto_escalate: true, allow_stubs: false, enforce_contracts: true, enforce_effects: true, enforce_budgets: false, enforce_capabilities: true, enforce_coverage: true, gate_on_score: false, require_docs_for_pub: true, require_tests_for_pub: true, forbid_unsafe_no_reason: true, forbid_all_unsafe: false, require_code_review: false, enforce_memory_safety: false, audit_dependencies: false }
    }
    
    pub fn production_config() -> ModeConfig {
        ModeConfig { mode: Mode::Production, auto_escalate: false, allow_stubs: false, enforce_contracts: true, enforce_effects: true, enforce_budgets: true, enforce_capabilities: true, enforce_coverage: true, gate_on_score: true, require_docs_for_pub: true, require_tests_for_pub: true, forbid_unsafe_no_reason: true, forbid_all_unsafe: false, require_code_review: false, enforce_memory_safety: true, audit_dependencies: false }
    }
    
    pub fn hardened_config() -> ModeConfig {
        ModeConfig { mode: Mode::Hardened, auto_escalate: false, allow_stubs: false, enforce_contracts: true, enforce_effects: true, enforce_budgets: true, enforce_capabilities: true, enforce_coverage: true, gate_on_score: true, require_docs_for_pub: true, require_tests_for_pub: true, forbid_unsafe_no_reason: true, forbid_all_unsafe: true, require_code_review: true, enforce_memory_safety: true, audit_dependencies: true }
    }
    
    pub fn config_for_mode(mode: Mode) -> ModeConfig {
        match mode { Mode::Dev => {
        dev_config()
    }, Mode::Strict => {
        strict_config()
    }, Mode::Production => {
        production_config()
    }, Mode::Hardened => {
        hardened_config()
    } }
    }
    
    pub fn parse_mode(s: String) -> Option<Mode> {
        match s.to_lowercase() { "dev" => {
        Option::Some(Mode::Dev)
    }, "strict" => {
        Option::Some(Mode::Strict)
    }, "production" => {
        Option::Some(Mode::Production)
    }, "hardened" => {
        Option::Some(Mode::Hardened)
    }, _ => {
        Option::None
    } }
    }
    
    pub fn mode_name(m: Mode) -> String {
        match m { Mode::Dev => {
        "Dev".to_string()
    }, Mode::Strict => {
        "Strict".to_string()
    }, Mode::Production => {
        "Production".to_string()
    }, Mode::Hardened => {
        "Hardened".to_string()
    } }
    }
    
    pub fn mode_ordinal(m: Mode) -> i64 {
        match m { Mode::Dev => {
        0
    }, Mode::Strict => {
        1
    }, Mode::Production => {
        2
    }, Mode::Hardened => {
        3
    } }
    }
    
    pub fn is_at_least(current: Mode, threshold: Mode) -> bool {
        mode_ordinal(current) >= mode_ordinal(threshold)
    }
    
