    #[derive(Clone)]
    struct ObjectFile {
        target: AsmTarget,
        text: Vec<u8>,
        data: Vec<u8>,
        rodata: Vec<u8>,
        bss_size: i64,
        symbols: Vec<AsmSymbol>,
        relocations: Vec<Relocation>,
        string_table: Vec<u8>,
        strings: Map<String, i64>,
    }
    
    pub fn object_new(target: AsmTarget) -> ObjectFile {
        let mut strtab = Vec::new();
        strtab.push(0);
        ObjectFile { target: target, text: Vec::new(), data: Vec::new(), rodata: Vec::new(), bss_size: 0, symbols: Vec::new(), relocations: Vec::new(), string_table: strtab, strings: BTreeMap::new() }
    }
    
    pub fn obj_add_string(obj: &mut ObjectFile, s: String) -> i64 {
        match obj.strings.get(&s) { Option::Some(off) => {
        return off;
    }, Option::None => {
        ()
    } };
        let off = (obj.string_table.len() as i64);
        for c in (s.bytes()).clone() {
            obj.string_table.push(c)
        }
        obj.string_table.push(0);
        obj.strings.insert(s, off);
        off
    }
    
