    pub fn LC_SEGMENT_64() -> u32 {
        0x19
    }
    
    pub fn LC_SYMTAB() -> u32 {
        0x02
    }
    
    pub fn LC_DYSYMTAB() -> u32 {
        0x0B
    }
    
    pub fn S_REGULAR() -> u32 {
        0
    }
    
    pub fn S_ZEROFILL() -> u32 {
        1
    }
    
    pub fn S_ATTR_PURE_INSTRUCTIONS() -> u32 {
        0x80000000
    }
    
    pub fn S_ATTR_SOME_INSTRUCTIONS() -> u32 {
        0x00000400
    }
    
    pub fn X86_64_RELOC_BRANCH_() -> u32 {
        2
    }
    
    pub fn X86_64_RELOC_SIGNED_() -> u32 {
        1
    }
    
    pub fn ARM64_RELOC_BRANCH26_() -> u32 {
        2
    }
    
    pub fn ARM64_RELOC_PAGE21_() -> u32 {
        3
    }
    
    pub fn ARM64_RELOC_PAGEOFF12_() -> u32 {
        4
    }
    
    pub fn build_macho64(obj: &ObjectFile) -> Vec<u8> {
        let mut out = Vec::new();
        let is_arm = match obj.target.arch { Arch::AArch64 => {
        true
    }, _ => {
        false
    } };
        let cputype = if is_arm {
        CPU_TYPE_ARM64()
    } else {
        CPU_TYPE_X86_64()
    };
        let cpusubtype = if is_arm {
        CPU_SUBTYPE_ARM64_ALL()
    } else {
        CPU_SUBTYPE_X86_64_ALL()
    };
        let text_size = (obj.text.len() as i64);
        let data_size = (obj.data.len() as i64);
        let rodata_size = (obj.rodata.len() as i64);
        let num_sections = 4;
        let segment_cmd_size = 72 + num_sections * 80;
        let symtab_cmd_size = 24;
        let dysymtab_cmd_size = 80;
        let num_load_cmds = 3;
        let load_cmds_size = segment_cmd_size + symtab_cmd_size + dysymtab_cmd_size;
        let header_size = 32;
        let text_offset = header_size + load_cmds_size;
        let data_offset = text_offset + text_size;
        let rodata_offset = data_offset + data_size;
        let segment_filesize = text_size + data_size + rodata_size;
        let mut reloc_buf = Vec::new();
        let mut text_nreloc = 0;
        let mut sym_name_to_idx = BTreeMap::new();
        let mut si = 0;
        for sym in (obj.symbols).clone() {
            sym_name_to_idx.insert(sym.name.clone(), si);
            si = si + 1;
        }
        for rel in (obj.relocations).clone() {
            let r_address = ((rel.offset) as u32);
            let sym_idx = match sym_name_to_idx.get(&rel.symbol.clone()) { Option::Some(idx) => {
        idx
    }, Option::None => {
        0
    } };
            let (r_type, r_pcrel, r_length) = if is_arm {
        match rel.kind { RelocKind::R_AARCH64_CALL26 => {
        (ARM64_RELOC_BRANCH26_(), ((1) as u32), ((2) as u32))
    }, RelocKind::R_AARCH64_ADR_PREL_PG_HI21 => {
        (ARM64_RELOC_PAGE21_(), ((1) as u32), ((2) as u32))
    }, RelocKind::R_AARCH64_ADD_ABS_LO12_NC => {
        (ARM64_RELOC_PAGEOFF12_(), ((0) as u32), ((2) as u32))
    }, RelocKind::ARM64_RELOC_BRANCH26 => {
        (ARM64_RELOC_BRANCH26_(), ((1) as u32), ((2) as u32))
    }, RelocKind::ARM64_RELOC_PAGE21 => {
        (ARM64_RELOC_PAGE21_(), ((1) as u32), ((2) as u32))
    }, RelocKind::ARM64_RELOC_PAGEOFF12 => {
        (ARM64_RELOC_PAGEOFF12_(), ((0) as u32), ((2) as u32))
    }, _ => {
        (((0) as u32), ((0) as u32), ((2) as u32))
    } }
    } else {
        match rel.kind { RelocKind::R_X86_64_PC32 => {
        (X86_64_RELOC_SIGNED_(), ((1) as u32), ((2) as u32))
    }, RelocKind::R_X86_64_PLT32 => {
        (X86_64_RELOC_BRANCH_(), ((1) as u32), ((2) as u32))
    }, RelocKind::R_X86_64_64 => {
        (((0) as u32), ((0) as u32), ((3) as u32))
    }, RelocKind::R_X86_64_GOTPCREL => {
        (((4) as u32), ((1) as u32), ((2) as u32))
    }, RelocKind::X86_64_RELOC_BRANCH => {
        (X86_64_RELOC_BRANCH_(), ((1) as u32), ((2) as u32))
    }, RelocKind::X86_64_RELOC_SIGNED => {
        (X86_64_RELOC_SIGNED_(), ((1) as u32), ((2) as u32))
    }, _ => {
        (((0) as u32), ((0) as u32), ((2) as u32))
    } }
    };
            let r_extern = 1;
            let packed = ((sym_idx) as u32) & 0x00FFFFFF | r_pcrel & 1 << 24 | r_length & 3 << 25 | r_extern & 1 << 27 | r_type & 0xF << 28;
            write32(&mut reloc_buf, r_address);
            write32(&mut reloc_buf, packed);
            text_nreloc = text_nreloc + 1;
        }
        let reloc_offset = align_up(rodata_offset + rodata_size, 4);
        let reloc_size = (reloc_buf.len() as i64);
        let mut mo_strtab = Vec::new();
        mo_strtab.push(0x20);
        mo_strtab.push(0);
        let mut nlist_buf = Vec::new();
        let mut n_local_syms = 0;
        let mut n_extern_syms = 0;
        for sym in (obj.symbols).clone() {
            let name_off = (mo_strtab.len() as i64);
            mo_strtab.push(0x5F);
            push_str(&mut mo_strtab, sym.name);
            let (n_type, is_ext) = match sym.binding { SymBinding::Local => {
        (((0x0E) as u8), false)
    }, SymBinding::Global => {
        (((0x0F) as u8), true)
    }, SymBinding::Weak => {
        (((0x0F) as u8), true)
    } };
            if is_ext {
        n_extern_syms = n_extern_syms + 1;
    } else {
        n_local_syms = n_local_syms + 1;
    };
            let n_sect = match sym.section { Section::Text => {
        1
    }, Section::Data => {
        2
    }, Section::Rodata => {
        3
    }, Section::Bss => {
        0
    } };
            let n_desc = match sym.binding { SymBinding::Weak => {
        0x0080
    }, _ => {
        0
    } };
            write32(&mut nlist_buf, ((name_off) as u32));
            nlist_buf.push(n_type);
            nlist_buf.push(n_sect);
            write16(&mut nlist_buf, n_desc);
            write64(&mut nlist_buf, ((sym.offset) as u64))
        }
        let symtab_offset = align_up(reloc_offset + reloc_size, 8);
        let strtab_offset = symtab_offset + (nlist_buf.len() as i64);
        write32(&mut out, MH_MAGIC_64());
        write32(&mut out, cputype);
        write32(&mut out, cpusubtype);
        write32(&mut out, MH_OBJECT());
        write32(&mut out, ((num_load_cmds) as u32));
        write32(&mut out, ((load_cmds_size) as u32));
        let hdr_flags = if (obj.relocations.len() as i64) > 0 {
        0x2000
    } else {
        0
    };
        write32(&mut out, hdr_flags);
        write32(&mut out, 0);
        write32(&mut out, LC_SEGMENT_64());
        write32(&mut out, ((segment_cmd_size) as u32));
        write_padded_str(&mut out, "".to_string(), 16);
        write64(&mut out, 0);
        let bss_size = obj.bss_size;
        write64(&mut out, ((segment_filesize + bss_size) as u64));
        write64(&mut out, ((text_offset) as u64));
        write64(&mut out, ((segment_filesize) as u64));
        write32(&mut out, 7);
        write32(&mut out, 7);
        write32(&mut out, ((num_sections) as u32));
        write32(&mut out, 0);
        write_padded_str(&mut out, "__text".to_string(), 16);
        write_padded_str(&mut out, "__TEXT".to_string(), 16);
        write64(&mut out, 0);
        write64(&mut out, ((text_size) as u64));
        write32(&mut out, ((text_offset) as u32));
        write32(&mut out, 4);
        if text_nreloc > 0 {
        write32(&mut out, ((reloc_offset) as u32));
        write32(&mut out, ((text_nreloc) as u32))
    } else {
        write32(&mut out, 0);
        write32(&mut out, 0)
    };
        write32(&mut out, S_REGULAR() | S_ATTR_PURE_INSTRUCTIONS() | S_ATTR_SOME_INSTRUCTIONS());
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write_padded_str(&mut out, "__data".to_string(), 16);
        write_padded_str(&mut out, "__DATA".to_string(), 16);
        write64(&mut out, ((text_size) as u64));
        write64(&mut out, ((data_size) as u64));
        write32(&mut out, ((data_offset) as u32));
        write32(&mut out, 3);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, S_REGULAR());
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write_padded_str(&mut out, "__const".to_string(), 16);
        write_padded_str(&mut out, "__TEXT".to_string(), 16);
        write64(&mut out, ((text_size + data_size) as u64));
        write64(&mut out, ((rodata_size) as u64));
        write32(&mut out, ((rodata_offset) as u32));
        write32(&mut out, 3);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, S_REGULAR());
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        let bss_vmaddr = ((text_size + data_size + rodata_size) as u64);
        write_padded_str(&mut out, "__bss".to_string(), 16);
        write_padded_str(&mut out, "__DATA".to_string(), 16);
        write64(&mut out, bss_vmaddr);
        write64(&mut out, ((bss_size) as u64));
        write32(&mut out, 0);
        write32(&mut out, 3);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, S_ZEROFILL());
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, LC_SYMTAB());
        write32(&mut out, ((symtab_cmd_size) as u32));
        write32(&mut out, ((symtab_offset) as u32));
        write32(&mut out, (((obj.symbols.len() as i64)) as u32));
        write32(&mut out, ((strtab_offset) as u32));
        write32(&mut out, (((mo_strtab.len() as i64)) as u32));
        write32(&mut out, LC_DYSYMTAB());
        write32(&mut out, ((dysymtab_cmd_size) as u32));
        write32(&mut out, 0);
        write32(&mut out, ((n_local_syms) as u32));
        write32(&mut out, ((n_local_syms) as u32));
        write32(&mut out, ((n_extern_syms) as u32));
        write32(&mut out, ((n_local_syms + n_extern_syms) as u32));
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, 0);
        append_vec(&mut out, &obj.text);
        append_vec(&mut out, &obj.data);
        append_vec(&mut out, &obj.rodata);
        pad_to(&mut out, reloc_offset);
        append_vec(&mut out, &reloc_buf);
        pad_to(&mut out, symtab_offset);
        append_vec(&mut out, &nlist_buf);
        append_vec(&mut out, &mo_strtab);
        out
    }
    
    pub fn IMAGE_FILE_MACHINE_AMD64() -> u16 {
        0x8664
    }
    
    pub fn IMAGE_FILE_MACHINE_ARM64() -> u16 {
        0xAA64
    }
    
    pub fn coff_machine(arch: Arch) -> u16 {
        match arch { Arch::X86_64 => {
        IMAGE_FILE_MACHINE_AMD64()
    }, Arch::AArch64 => {
        IMAGE_FILE_MACHINE_ARM64()
    } }
    }
    
    pub fn coff_text_reloc_type(arch: Arch, kind: RelocKind) -> u16 {
        match arch { Arch::X86_64 => {
        match kind { RelocKind::R_X86_64_64 => {
        1
    }, RelocKind::R_X86_64_PC32 => {
        4
    }, RelocKind::R_X86_64_PLT32 => {
        4
    }, _ => {
        0
    } }
    }, Arch::AArch64 => {
        match kind { RelocKind::R_AARCH64_CALL26 => {
        0x0003
    }, RelocKind::R_AARCH64_ADR_PREL_PG_HI21 => {
        0x0004
    }, RelocKind::R_AARCH64_ADD_ABS_LO12_NC => {
        0x0006
    }, RelocKind::R_AARCH64_LDST16_ABS_LO12_NC => {
        0x0007
    }, RelocKind::R_AARCH64_LDST64_ABS_LO12_NC => {
        0x0007
    }, RelocKind::R_AARCH64_LDST32_ABS_LO12_NC => {
        0x0007
    }, RelocKind::R_AARCH64_LDST8_ABS_LO12_NC => {
        0x0007
    }, RelocKind::R_AARCH64_CONDBR19 => {
        0x000F
    }, RelocKind::R_AARCH64_PREL32 => {
        0x0011
    }, _ => {
        0
    } }
    } }
    }
    
    pub fn IMAGE_SCN_CNT_CODE() -> u32 {
        0x00000020
    }
    
    pub fn IMAGE_SCN_CNT_INITIALIZED() -> u32 {
        0x00000040
    }
    
    pub fn IMAGE_SCN_CNT_UNINITIALIZED() -> u32 {
        0x00000080
    }
    
    pub fn IMAGE_SCN_MEM_EXECUTE() -> u32 {
        0x20000000
    }
    
    pub fn IMAGE_SCN_MEM_READ() -> u32 {
        0x40000000
    }
    
    pub fn IMAGE_SCN_MEM_WRITE() -> u32 {
        0x80000000
    }
    
    pub fn build_coff64(obj: &ObjectFile) -> Vec<u8> {
        let mut out = Vec::new();
        let num_sections = 3;
        let mut text_reloc_buf = Vec::new();
        let mut text_nrelocs = 0;
        let mut sym_name_to_idx = BTreeMap::new();
        let mut si = 0;
        for sym in (obj.symbols).clone() {
            sym_name_to_idx.insert(sym.name.clone(), si);
            si = si + 1;
        }
        for rel in (obj.relocations).clone() {
            let sym_idx = match sym_name_to_idx.get(&rel.symbol.clone()) { Option::Some(idx) => {
        idx
    }, Option::None => {
        0
    } };
            let reloc_type = coff_text_reloc_type(obj.target.arch, rel.kind);
            write32(&mut text_reloc_buf, ((rel.offset) as u32));
            write32(&mut text_reloc_buf, ((sym_idx) as u32));
            write16(&mut text_reloc_buf, reloc_type);
            text_nrelocs = text_nrelocs + 1;
        }
        write16(&mut out, coff_machine(obj.target.arch));
        write16(&mut out, ((num_sections) as u16));
        write32(&mut out, 0);
        let symtab_placeholder = (out.len() as i64);
        write32(&mut out, 0);
        write32(&mut out, (((obj.symbols.len() as i64)) as u32));
        write16(&mut out, 0);
        write16(&mut out, 0);
        let headers_end = 20 + num_sections * 40;
        let text_off = headers_end;
        let data_off = text_off + (obj.text.len() as i64);
        let rdata_off = data_off + (obj.data.len() as i64);
        let reloc_off = rdata_off + (obj.rodata.len() as i64);
        let reloc_size = (text_reloc_buf.len() as i64);
        write_padded_str(&mut out, ".text".to_string(), 8);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, (((obj.text.len() as i64)) as u32));
        write32(&mut out, ((text_off) as u32));
        if text_nrelocs > 0 {
        write32(&mut out, ((reloc_off) as u32))
    } else {
        write32(&mut out, 0)
    };
        write32(&mut out, 0);
        write16(&mut out, text_nrelocs);
        write16(&mut out, 0);
        write32(&mut out, IMAGE_SCN_CNT_CODE() | IMAGE_SCN_MEM_EXECUTE() | IMAGE_SCN_MEM_READ());
        write_padded_str(&mut out, ".data".to_string(), 8);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, (((obj.data.len() as i64)) as u32));
        write32(&mut out, ((data_off) as u32));
        write32(&mut out, 0);
        write32(&mut out, 0);
        write16(&mut out, 0);
        write16(&mut out, 0);
        write32(&mut out, IMAGE_SCN_CNT_INITIALIZED() | IMAGE_SCN_MEM_READ() | IMAGE_SCN_MEM_WRITE());
        write_padded_str(&mut out, ".rdata".to_string(), 8);
        write32(&mut out, 0);
        write32(&mut out, 0);
        write32(&mut out, (((obj.rodata.len() as i64)) as u32));
        write32(&mut out, ((rdata_off) as u32));
        write32(&mut out, 0);
        write32(&mut out, 0);
        write16(&mut out, 0);
        write16(&mut out, 0);
        write32(&mut out, IMAGE_SCN_CNT_INITIALIZED() | IMAGE_SCN_MEM_READ());
        append_vec(&mut out, &obj.text);
        append_vec(&mut out, &obj.data);
        append_vec(&mut out, &obj.rodata);
        append_vec(&mut out, &text_reloc_buf);
        let symtab_pos = (out.len() as i64);
        patch_u32(&mut out, symtab_placeholder, ((symtab_pos) as u32));
        let mut coff_strtab = Vec::new();
        let strtab_size_placeholder = (coff_strtab.len() as i64);
        write32(&mut coff_strtab, 0);
        for sym in (obj.symbols).clone() {
            let name_bytes = sym.name.bytes();
            if (name_bytes.len() as i64) <= 8 {
        write_padded_str(&mut out, sym.name, 8)
    } else {
        let str_off = (coff_strtab.len() as i64);
        push_str(&mut coff_strtab, sym.name);
        write32(&mut out, 0);
        write32(&mut out, ((str_off) as u32))
    };
            write32(&mut out, ((sym.offset) as u32));
            let sec_num = match sym.section { Section::Text => {
        1
    }, Section::Data => {
        2
    }, Section::Rodata => {
        3
    }, Section::Bss => {
        0
    } };
            write16(&mut out, sec_num);
            let sym_type = match sym.kind { SymKind::Func => {
        0x20
    }, _ => {
        0
    } };
            write16(&mut out, sym_type);
            let storage = match sym.binding { SymBinding::Global => {
        2
    }, SymBinding::Local => {
        3
    }, SymBinding::Weak => {
        2
    } };
            out.push(storage);
            out.push(0)
        }
        patch_u32(&mut coff_strtab, strtab_size_placeholder, (((coff_strtab.len() as i64)) as u32));
        append_vec(&mut out, &coff_strtab);
        out
    }
    
    pub fn build_object(obj: &ObjectFile) -> Vec<u8> {
        match obj.target.os { OsAbi::Linux => {
        build_elf64(obj)
    }, OsAbi::MacOS => {
        build_macho64(obj)
    }, OsAbi::Windows => {
        build_coff64(obj)
    } }
    }
    
    pub fn push_str(v: &mut Vec<u8>, s: String) -> () {
        for c in (s.bytes()).clone() {
            v.push(c)
        }
        v.push(0);
    }
    
    pub fn write16(v: &mut Vec<u8>, val: u16) -> () {
        v.push(((val & 0xFF) as u8));
        v.push(((val >> 8 & 0xFF) as u8));
    }
    
    pub fn write32(v: &mut Vec<u8>, val: u32) -> () {
        v.push(((val & 0xFF) as u8));
        v.push(((val >> 8 & 0xFF) as u8));
        v.push(((val >> 16 & 0xFF) as u8));
        v.push(((val >> 24 & 0xFF) as u8));
    }
    
    pub fn write64(v: &mut Vec<u8>, val: u64) -> () {
        write32(v, ((val & 0xFFFFFFFF) as u32));
        write32(v, ((val >> 32 & 0xFFFFFFFF) as u32));
    }
    
    pub fn emit_zeros_vec(v: &mut Vec<u8>, n: i64) -> () {
        v.extend(&Vec::filled(n, 0u8));
    }
    
    pub fn append_vec(dst: &mut Vec<u8>, src: &Vec<u8>) -> () {
        dst.extend(src);
    }
    
    pub fn pad_to(v: &mut Vec<u8>, target: i64) -> () {
        while (v.len() as i64) < target {
            v.push(0)
        }
    }
    
    pub fn write_padded_str(v: &mut Vec<u8>, s: String, len: i64) -> () {
        let mut i = 0;
        for c in (s.bytes()).clone() {
            if i < len {
        v.push(c);
        i = i + 1;
    }
        }
        while i < len {
            v.push(0);
            i = i + 1;
        }
    }
    
    pub fn patch_u32(v: &mut Vec<u8>, offset: i64, val: u32) -> () {
        v[(offset) as usize] = ((val & 0xFF) as u8);
        v[(offset + 1) as usize] = ((val >> 8 & 0xFF) as u8);
        v[(offset + 2) as usize] = ((val >> 16 & 0xFF) as u8);
        v[(offset + 3) as usize] = ((val >> 24 & 0xFF) as u8);
    }
    
    pub fn align_up(val: i64, align: i64) -> i64 {
        val + align - 1 / align * align
    }
    
