    pub fn debug_info_new(arch: Arch) -> ObjectDebugInfo {
        let mut str_table = Vec::new();
        str_table.push(0);
        ObjectDebugInfo { arch: arch, debug_abbrev: Vec::new(), debug_info: Vec::new(), debug_line: Vec::new(), debug_str: str_table, debug_aranges: Vec::new(), debug_frame: Vec::new(), str_offsets: BTreeMap::new(), next_die_offset: 0, type_die_offsets: BTreeMap::new() }
    }
    
    pub fn dwarf_add_string(di: &mut ObjectDebugInfo, s: String) -> i64 {
        match di.str_offsets.get(&s.clone()) { Option::Some(off) => {
        return off;
    }, Option::None => {
        ()
    } };
        let off = (di.debug_str.len() as i64);
        for c in (s.bytes()).clone() {
            di.debug_str.push(c)
        }
        di.debug_str.push(0);
        di.str_offsets.insert(s, off);
        off
    }
    
    pub fn emit_uleb128(v: &mut Vec<u8>, value: u64) -> () {
        loop {
            let mut byte = ((value & 0x7F) as u8);
            value = value >> 7;
            if value != 0 {
        byte = byte | 0x80;
    };
            v.push(byte);
            if value == 0 {
        break;
    }
        }
    }
    
    pub fn emit_sleb128(v: &mut Vec<u8>, value: i64) -> () {
        let negative = value < 0;
        loop {
            let mut byte = ((value & 0x7F) as u8);
            value = value >> 7;
            let more = !value == 0 && byte & 0x40 == 0 || value == -1 && byte & 0x40 != 0;
            if more {
        byte = byte | 0x80;
    };
            v.push(byte);
            if !more {
        break;
    }
        }
    }
    
    pub fn generate_dwarf_debug_info(di: &mut ObjectDebugInfo, source_file: String, comp_dir: String, producer: String, functions: &Vec<FunctionObjectDebugInfo>, text_size: u64) -> () {
        generate_abbrev_table(di);
        let abbrev_offset = 0u32;
        let addr_size = 8u8;
        let unit_start = (di.debug_info.len() as i64);
        write32(&mut di.debug_info, 0);
        write16(&mut di.debug_info, 4);
        write32(&mut di.debug_info, abbrev_offset);
        di.debug_info.push(addr_size);
        emit_uleb128(&mut di.debug_info, 1);
        let producer_off = dwarf_add_string(di, producer.clone());
        write32(&mut di.debug_info, ((producer_off) as u32));
        write16(&mut di.debug_info, DW_LANG_Tangerine());
        let name_off = dwarf_add_string(di, source_file.clone());
        write32(&mut di.debug_info, ((name_off) as u32));
        let dir_off = dwarf_add_string(di, comp_dir.clone());
        write32(&mut di.debug_info, ((dir_off) as u32));
        write64(&mut di.debug_info, 0);
        write64(&mut di.debug_info, text_size);
        write32(&mut di.debug_info, 0);
        emit_base_types(di);
        for func in (functions).clone() {
            emit_function_die(di, func)
        }
        di.debug_info.push(0);
        let unit_length = (di.debug_info.len() as i64) - unit_start - 4;
        patch_u32(&mut di.debug_info, unit_start, ((unit_length) as u32));
        generate_line_info(di, source_file.clone(), functions);
        generate_aranges(di, text_size);
        generate_frame_info(di);
    }
    
