        let mut items = Vec::new();
        while !at(p, TokenKind::End) && !at(p, TokenKind::Eof) {
            skip_newlines(p);
            if at(p, TokenKind::End) {
        break;
    };
            if at(p, TokenKind::Def) {
        advance(p);
        match parse_extern_fn(p) { Option::Some(f) => {
        items.push(ExternItem::Function(f))
    }, Option::None => {
        synchronize(p)
    } }
    } else if at(p, TokenKind::Static) {
        advance(p);
        match parse_extern_static(p) { Option::Some(s) => {
        items.push(ExternItem::Static(s))
    }, Option::None => {
        synchronize(p)
    } }
    } else {
        synchronize(p)
    }
        }
        expect_end(p);
        Option::Some(ExternBlock { abi: abi, items: items, span: span_merge(start, peek_span(p)) })
