                    if self.pos < (self.src.len() as i64) && self.peek() == '}' {
                self.advance();
                return Ok(TomlValue::Table(table));
            };
                    loop {
                        self.skip_ws();
                        let key = self.parse_key()?;
                        self.skip_ws();
                        self.expect('=')?;
                        self.skip_ws();
                        let val = self.parse_value()?;
                        table.insert(key, val);
                        self.skip_ws();
                        if self.pos >= (self.src.len() as i64) {
                break;
            };
                        if self.peek() == ',' {
                self.advance()
            } else if self.peek() == '}' {
                break;
            } else {
                break;
            }
                    }
                    self.expect('}')?;
                    Ok(TomlValue::Table(table))
