                    if self.pos + n > (self.src.len() as i64) {
                return Err(PkgError::ParseError(("unexpected end reading escape".to_string()).to_string()));
            };
                    let result = self.src.substring(self.pos, self.pos + n);
                    self.pos = self.pos + n;
