                    let pkg_edition = _extract_toml_field(content.clone(), ("edition".to_string()).to_string()).unwrap_or(("2024".to_string()).to_string());
                    let pkg_license = _extract_toml_field(content.clone(), ("license".to_string()).to_string());
                    let pkg_description = _extract_toml_field(content.clone(), ("description".to_string()).to_string());
                    let pkg_repository = _extract_toml_field(content.clone(), ("repository".to_string()).to_string());
                    let deps = _parse_toml_deps(content.clone(), ("[dependencies]".to_string()).to_string());
                    let dev_deps = _parse_toml_deps(content.clone(), ("[dev-dependencies]".to_string()).to_string());
