        register_primitive(&mut env, "UInt".to_string());
        register_primitive(&mut env, "Float".to_string());
        register_primitive(&mut env, "Char".to_string());
        register_primitive(&mut env, "String".to_string());
        register_primitive(&mut env, "Never".to_string());
        register_primitive(&mut env, "i8".to_string());
        register_primitive(&mut env, "i16".to_string());
        register_primitive(&mut env, "i32".to_string());
        register_primitive(&mut env, "i64".to_string());
        register_primitive(&mut env, "u8".to_string());
        register_primitive(&mut env, "u16".to_string());
        register_primitive(&mut env, "u32".to_string());
        register_primitive(&mut env, "u64".to_string());
        register_primitive(&mut env, "f32".to_string());
        register_primitive(&mut env, "f64".to_string());
        register_builtin_generic(&mut env, "Ptr".to_string(), 1, TypeDefKind::Opaque);
        register_builtin_generic(&mut env, "PtrMut".to_string(), 1, TypeDefKind::Opaque);
        register_builtin_generic(&mut env, "Box".to_string(), 1, TypeDefKind::Opaque);
        register_builtin_generic(&mut env, "Rc".to_string(), 1, TypeDefKind::Opaque);
        register_builtin_generic(&mut env, "Option".to_string(), 1, TypeDefKind::Enum(vec![VariantInfo { name: "Some".to_string(), fields: vec![Type::Param("T".to_string())], discriminant: 0 }, VariantInfo { name: "None".to_string(), fields: Vec::new(), discriminant: 1 }]));
        register_builtin_generic(&mut env, "Result".to_string(), 2, TypeDefKind::Enum(vec![VariantInfo { name: "Ok".to_string(), fields: vec![Type::Param("T".to_string())], discriminant: 0 }, VariantInfo { name: "Err".to_string(), fields: vec![Type::Param("E".to_string())], discriminant: 1 }]));
        register_builtin_generic(&mut env, "Vec".to_string(), 1, TypeDefKind::Struct(vec![FieldInfo { name: "ptr".to_string(), ty: Type::Param("T".to_string()), is_public: false }, FieldInfo { name: "len".to_string(), ty: Type::Int, is_public: true }, FieldInfo { name: "cap".to_string(), ty: Type::Int, is_public: false }]));
        register_builtin_generic(&mut env, "Map".to_string(), 2, TypeDefKind::Struct(Vec::new()));
        register_builtin_generic(&mut env, "Set".to_string(), 1, TypeDefKind::Struct(Vec::new()));
        register_builtin_trait(&mut env, "Copy".to_string(), Vec::new());
        register_builtin_trait(&mut env, "Drop".to_string(), vec![MethodSig { name: "drop".to_string(), params: Vec::new(), ret_type: Type::Unit, is_method: true, param_types: Vec::new(), return_type: Type::Unit }]);
        register_builtin_trait(&mut env, "Clone".to_string(), vec![MethodSig { name: "clone".to_string(), params: Vec::new(), ret_type: Type::Param("Self".to_string()), is_method: true, param_types: Vec::new(), return_type: Type::Param("Self".to_string()) }]);
        register_builtin_trait(&mut env, "Display".to_string(), vec![MethodSig { name: "to_string".to_string(), params: Vec::new(), ret_type: Type::String, is_method: true, param_types: Vec::new(), return_type: Type::String }]);
        register_builtin_trait(&mut env, "Debug".to_string(), vec![MethodSig { name: "debug_string".to_string(), params: Vec::new(), ret_type: Type::String, is_method: true, param_types: Vec::new(), return_type: Type::String }]);
        register_builtin_trait(&mut env, "Iterator".to_string(), vec![MethodSig { name: "next".to_string(), params: Vec::new(), ret_type: Type::Option(Type::Param("Item".to_string())), is_method: true, param_types: Vec::new(), return_type: Type::Option(Type::Param("Item".to_string())) }]);
        register_builtin_trait(&mut env, "Send".to_string(), Vec::new());
