        register_builtin_trait(&mut env, "Ord".to_string(), vec![MethodSig { name: "cmp".to_string(), params: vec![Type::Param("Self".to_string())], ret_type: Type::Int, is_method: true, param_types: vec![Type::Param("Self".to_string())], return_type: Type::Int }]);
        register_builtin_trait(&mut env, "Hash".to_string(), vec![MethodSig { name: "hash".to_string(), params: Vec::new(), ret_type: Type::Int, is_method: true, param_types: Vec::new(), return_type: Type::Int }]);
        register_builtin_trait(&mut env, "Default".to_string(), vec![MethodSig { name: "default".to_string(), params: Vec::new(), ret_type: Type::Param("Self".to_string()), is_method: false, param_types: Vec::new(), return_type: Type::Param("Self".to_string()) }]);
        register_builtin_trait(&mut env, "Into".to_string(), vec![MethodSig { name: "into".to_string(), params: Vec::new(), ret_type: Type::Param("T".to_string()), is_method: true, param_types: Vec::new(), return_type: Type::Param("T".to_string()) }]);
        register_builtin_trait(&mut env, "From".to_string(), vec![MethodSig { name: "from".to_string(), params: vec![Type::Param("T".to_string())], ret_type: Type::Param("Self".to_string()), is_method: false, param_types: vec![Type::Param("T".to_string())], return_type: Type::Param("Self".to_string()) }]);
